('0f7bbc4d-5b53-5ed5-8f74-9c29dd8f3935','b609ba78-7c54-515c-93f2-7d28967389c6',10,'travel','سفر','spoken & written','to change from one bus , plane etc to another while you are travelling , or arrange for someone to do this','[ intransitive, transitive ]',null,'برای تغییر از یک اتوبوس، هواپیما و غیره در حین سفر، یا قرار دادن شخصی برای انجام این کار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You will be met on arrival at the airport and transferred to your hotel.","translation":"در بدو ورود در فرودگاه با شما روبرو می شوید و به هتل خود منتقل می شوید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000553959.mp3"}]'::jsonb,1),
('7e9d26d3-422c-5fe9-acea-eaaecd20f1c4','b609ba78-7c54-515c-93f2-7d28967389c6',11,'information/music','اطلاعات/موسیقی','spoken & written','to copy recorded information, music etc from one system to another','[ transitive ]',null,'برای کپی کردن اطلاعات ضبط شده، موسیقی و غیره از یک سیستم به سیستم دیگر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Transfer the files onto a memory stick.","translation":"فایل ها را به حافظه جانبی منتقل کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00911.mp3"}]'::jsonb,1),
('f1ba6b1e-b809-57a7-b5fa-eecc18f9e3ed','b609ba78-7c54-515c-93f2-7d28967389c6',12,'disease','بیماری','spoken & written','if a disease is transferred from one person or animal to another, the second person or animal begins to have the disease','[ transitive ]',null,'اگر بیماری از یک فرد یا حیوان به دیگری منتقل شود، فرد یا حیوان دوم شروع به ابتلا به این بیماری می کند',array['pass']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It is unlikely that the disease will be transferred from animals to humans.","translation":"بعید است که بیماری از حیوانات به انسان منتقل شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001613554.mp3"}]'::jsonb,1),
