('c53fb4cb-10e8-5355-9435-12682e506706','c04690a2-0db3-5593-8ca5-fb2dad7f1f2c',1,null,null,'spoken & written','someone’s ultimate aim is their main and most important aim, that they hope to achieve in the future',null,null,'نهایی، غایی (هدف)؛ نهایی (فرد)؛ نهایی (پیش',array['final']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Complete disarmament was the ultimate goal of the conference.","translation":"خلع سلاح کامل هدف نهایی کنفرانس بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617557.mp3"},{"sentence":"Our ultimate objective is to have as many female members of parliament as there are male.","translation":"هدف نهایی ما این است که به تعداد مردان نماینده زن در پارلمان داشته باشیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617558.mp3"}]'::jsonb,2),
('25c1f51f-6a43-5f56-8290-7f0f3983308b','c04690a2-0db3-5593-8ca5-fb2dad7f1f2c',2,null,null,'spoken & written','the ultimate result of a long process is what happens at the end of it',null,null,'نتیجه نهایی یک فرآیند طولانی این است که در پایان آن اتفاق بیفتد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The ultimate outcome of the experiment cannot be predicted.","translation":"نتیجه نهایی آزمایش را نمی توان پیش بینی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617564.mp3"},{"sentence":"The ultimate fate of the tribe was even sadder.","translation":"سرنوشت نهایی قبیله غم انگیزتر بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617565.mp3"},{"sentence":"the ultimate failure of the project","translation":"شکست نهایی پروژه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617566.mp3"}]'::jsonb,3),
('25af0468-b141-5182-9c7c-13e3b47e8bf1','c04690a2-0db3-5593-8ca5-fb2dad7f1f2c',3,null,null,'spoken & written','if you have ultimate responsibility for something, you are the person who must make the important final decisions about it',null,null,'اگر مسئولیت نهایی چیزی را دارید، شما کسی هستید که باید تصمیمات نهایی مهم را در مورد آن بگیرید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The ultimate responsibility for policy lies with the president.","translation":"مسئولیت نهایی سیاست بر عهده رئیس جمهور است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000543828.mp3"},{"sentence":"The ultimate decision rests with the Public Health Service.","translation":"تصمیم نهایی با خدمات بهداشت عمومی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617569.mp3"}]'::jsonb,2),
('34e30728-19f3-5f32-b63a-4bdb57d1ceca','c04690a2-0db3-5593-8ca5-fb2dad7f1f2c',4,null,null,'spoken & written','better, bigger, worse etc than all other things or people of the same kind',null,null,'بهتر، بزرگتر، بدتر و غیره از همه چیزها یا افراد مشابه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Rolling Stones are the ultimate rock and roll band.","translation":"رولینگ استونز بهترین گروه راک اند رول است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020297.mp3"},{"sentence":"The female nude is surely the ultimate test of artistic skill.","translation":"برهنه زن مطمئناً آزمون نهایی مهارت هنری است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001617573.mp3"}]'::jsonb,2),
