('68b4fe9c-daf7-5d5f-882a-5bb9c05e0928','edf08e15-3e89-5e1b-b193-d63378432932',1,null,null,'spoken & written','towards or on an upper floor in a building',null,null,'طبقه بالا، بالای طبقه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I went upstairs and had a shower.","translation":"رفتم بالا و دوش گرفتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000526442.mp3"},{"sentence":"She’s upstairs in bed feeling ill.","translation":"او در طبقه بالا در رختخواب است که احساس بیماری می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001620032.mp3"}]'::jsonb,2),
