('040fc89d-e40f-58ef-b53b-ec94cb2a6744','377e83b4-e5c3-5fa5-bd2a-d96911b78631',1,null,null,'spoken & written','a holiday , or time spent not working','[ countable, uncountable ]',null,'مرخصی، تعطیلات؛ سفر تعطیلات (فرد)','{}'::text[],'{}'::text[],array['take/have a vacation We usually take a vacation once a year.','go on vacation I’m going on vacation next month.','need a vacation You’re working too hard. You need a vacation.','spend a vacation Where did you spend your vacation?','a summer vacation What did you do on your summer vacation?','a family vacation We had to cancel the family vacation.','a long vacation She decided to take a long vacation.','a short vacation a short vacation at the beach','a two-week/three-day etc vacation','a vacation spot (= a place for a vacation ) The island is my favorite vacation spot.','a vacation day (= a day away from work on vacation ) You could take a sick day or a vacation day.','vacation plans (= an idea about what you want to do on your vacation ) Do you have any vacation plans this summer?']::text[],'[{"sentence":"We’re planning a vacation in Europe.","translation":"ما در حال برنامه ریزی برای تعطیلات در اروپا هستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001690.mp3"},{"sentence":"He’s on vacation this week.","translation":"او این هفته در تعطیلات است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040294.mp3"},{"sentence":"We’re planning to go on vacation soon.","translation":"ما قصد داریم به زودی به تعطیلات برویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040295.mp3"}]'::jsonb,3),
