('b05a13d2-d033-5791-a5ce-e4ca3d27c24c','631767d6-c85c-5977-a707-e96dda2c5628',4,'character','شخصیت','spoken & written','lack of determination shown in someone’s behaviour','[ uncountable ]',null,'عدم عزم نشان داده شده در رفتار کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He couldn’t explain his weakness in giving in to her demands.","translation":"او نمی توانست ضعف خود را در تسلیم شدن به خواسته های او توضیح دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001642593.mp3"},{"sentence":"I dared not cry or show any sign of weakness .","translation":"جرات نکردم گریه کنم یا نشانه ای از ضعف نشان دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001642594.mp3"},{"sentence":"his weakness of character","translation":"ضعف شخصیت او","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001642600.mp3"}]'::jsonb,3),
