('22e0a330-d23c-50ee-ae18-78c7e87d69bd','f8e85cc6-bd1f-52a3-a2c7-54165c36c57b',2,null,null,'spoken & written','used to say that it is not important what happens, what you do etc because it does not change the situation',null,null,'می گفت مهم نیست چه اتفاقی می افتد، چه کاری انجام می دهید و غیره زیرا این وضعیت را تغییر نمی دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Whatever I suggest, he always disagrees.","translation":"هر چه من پیشنهاد می کنم، او همیشه مخالف است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000516906.mp3"},{"sentence":"The building must be saved, whatever the cost.","translation":"ساختمان باید صرفه جویی شود، به هر قیمتی که باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000516907.mp3"},{"sentence":"If you are unable to attend the interview, for whatever reason, you should inform us immediately.","translation":"اگر به هر دلیلی نتوانستید در مصاحبه شرکت کنید، باید سریعاً به ما اطلاع دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001814145.mp3"}]'::jsonb,3),
('846180bb-074f-5733-85bc-a326a05c6f9e','f8e85cc6-bd1f-52a3-a2c7-54165c36c57b',3,null,null,'spoken & written',null,null,'whatever you do','هر چه، هر چیزی (بدون قید)؛ هر چه که (باز)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
