('91390995-bcbd-5fde-a40f-629bf3145e29','f8e85cc6-bd1f-52a3-a2c7-54165c36c57b',5,null,null,'spoken & written',null,null,'... or/and whatever (else)','هر چه، هر چیزی (بدون قید)؛ هر چه که (باز)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a9fb4540-3e7c-5763-96a7-c80bd0ed0338','f8e85cc6-bd1f-52a3-a2c7-54165c36c57b',6,null,null,'spoken & written','used when asking a question to emphasize that you are surprised or slightly angry about something',null,null,'هنگام پرسیدن سؤال برای تأکید بر اینکه از چیزی متعجب یا کمی عصبانی هستید استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Whatever can he mean?","translation":"منظور او هر چه می تواند باشد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000516931.mp3"},{"sentence":"‘Did you know she’s dyed her hair orange?’ ‘ Whatever next? ’","translation":"\"آیا می دانستی که او موهایش را نارنجی رنگ کرده است؟\" ''","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001606300.mp3"}]'::jsonb,2),
