('54376505-833b-59f7-90b2-7f5e3f4cf7be','cacadd66-a841-5059-a1a0-d0df4035c45b',1,null,null,'spoken & written','used to emphasize a negative statement',null,null,'برای تاکید بر گزاره منفی استفاده می شود',array['whatsoever']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She has shown no interest whatever in anything scientific.","translation":"او هیچ علاقه ای به هیچ چیز علمی نشان نداده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001814153.mp3"},{"sentence":"This is just a stupid argument that has nothing whatever to do with your job.","translation":"این فقط یک استدلال احمقانه است که ربطی به شغل شما ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000516956.mp3"}]'::jsonb,2),
('f745b936-e170-52c2-8967-ee0c173ce6c6','fba7c51f-047b-5db5-b53a-f673ccf16573',1,null,null,'spoken & written','every time that a particular thing happens',null,null,'هر وقت، هر زمان (تکرار)؛ وقتی (تکرار)؛ هر وقت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Larry always blames me whenever anything goes wrong.","translation":"لری همیشه هر وقت مشکلی پیش بیاید مرا سرزنش می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517521.mp3"},{"sentence":"Whenever I hear that tune, it makes me think of you.","translation":"هر وقت آن آهنگ را می شنوم، باعث می شود به تو فکر کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001814195.mp3"}]'::jsonb,2),
('c7a6110c-0724-5c4c-a003-c218090e5206','fba7c51f-047b-5db5-b53a-f673ccf16573',2,null,null,'spoken & written','at any time',null,null,'در هر زمان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Come and visit me whenever you want.","translation":"هر وقت خواستی به من سر بزن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001636750.mp3"},{"sentence":"a policy of using recycled paper whenever possible","translation":"سیاست استفاده از کاغذ بازیافتی در صورت امکان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517522.mp3"}]'::jsonb,2),
('95ef55a4-31e0-5e70-8456-af74fe0c54bd','fba7c51f-047b-5db5-b53a-f673ccf16573',3,null,null,'spoken','used as a reply to say that it does not matter what time something happens',null,null,'به عنوان پاسخ برای گفتن این که مهم نیست در چه ساعتی اتفاقی می افتد استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘I’ll call you tomorrow or the day after.’ ‘Okay. Whenever.’","translation":"«فردا یا پس فردا با شما تماس می‌گیرم.» «باشه. هر وقت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517532.mp3"}]'::jsonb,1),
('5cf4f51a-0320-50bf-9e46-f91c0a0b861c','a67a22aa-f042-5e27-a58f-de3f6fca3de4',1,null,null,'spoken & written','to or at any place, position , or situation',null,null,'هر جا، در هر جای؛ هر جا که (تأکید)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Children will play wherever they happen to be.","translation":"بچه ها هر جا که باشند بازی خواهند کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517746.mp3"},{"sentence":"Sit wherever you like.","translation":"هرجا دوست داری بشین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517747.mp3"},{"sentence":"Dublin people dress more individually than people in London or wherever.","translation":"مردم دوبلین بیشتر از افرادی که در لندن یا هر جای دیگری هستند لباس جداگانه می پوشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517751.mp3"}]'::jsonb,3),
('e4335dae-a11d-5f01-9628-ffd802e97731','a67a22aa-f042-5e27-a58f-de3f6fca3de4',2,null,null,'spoken & written','in all places that',null,null,'در همه جاهایی که','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She is shadowed by detectives wherever she goes.","translation":"هر جا که می رود زیر سایه کارآگاهان قرار می گیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001636764.mp3"},{"sentence":"I feel I ought to be nice to them wherever possible (= at all times when it is possible ) .","translation":"من احساس می کنم باید هر جا که ممکن است با آنها مهربان باشم (= در هر زمان که ممکن است).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517756.mp3"}]'::jsonb,2),
('b57e6a1b-24d5-50fd-88de-d9dcd046b7f4','a67a22aa-f042-5e27-a58f-de3f6fca3de4',3,null,null,'spoken & written','used at the beginning of a question to show surprise',null,null,'در ابتدای سوال برای نشان دادن تعجب استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Wherever did she find that?’ Daisy wondered.","translation":"دیزی با تعجب گفت: «هر کجا این را پیدا کرد؟»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000517760.mp3"}]'::jsonb,1),
('f12a6b6d-2b1c-5dd9-9fd8-aed28fc93497','a67a22aa-f042-5e27-a58f-de3f6fca3de4',4,null,null,'spoken & written',null,null,'wherever that is/may be','هر جا، در هر جای؛ هر جا که (تأکید)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('2f18c019-b0eb-5559-a147-5682f7cfeb69','9293f094-d170-52ef-bd46-6d5bc7127652',1,'not take part','شرکت نکن','spoken & written','to stop taking part in an activity , belonging to an organization etc, or to make someone do this','[ intransitive, transitive ]',null,'برکنار شدن؛ عقب کشیدن (پول)؛ بیرون کشیدن (چوب)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A knee injury forced her to withdraw from the competition.","translation":"آسیب دیدگی زانو او را مجبور به کناره گیری از مسابقات کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494194.mp3"},{"sentence":"calls for Britain to withdraw from the European Union","translation":"خواستار خروج بریتانیا از اتحادیه اروپا شد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494187.mp3"},{"sentence":"Parents have the right to withdraw their children from religious education lessons if they wish.","translation":"والدین حق دارند در صورت تمایل فرزندان خود را از دروس معارف دینی کنار بگذارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626639.mp3"},{"sentence":"She pulled out with a knee injury.","translation":"او با مصدومیت از ناحیه زانو بیرون آمد.","audio_url":null}]'::jsonb,4),
('c67873ed-84ee-5c7b-b00a-12b9bfc67f81','9293f094-d170-52ef-bd46-6d5bc7127652',2,'stop supporting','دست از حمایت بردارید','spoken & written','to stop giving support or money to someone or something, especially as the result of an official decision','[ transitive ]',null,'متوقف کردن حمایت یا پول به کسی یا چیزی، به ویژه در نتیجه یک تصمیم رسمی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"One of the minority parties had withdrawn its support for Chancellor Kohl.","translation":"یکی از احزاب اقلیت حمایت خود از صدراعظم کوهل را پس گرفته بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494165.mp3"},{"sentence":"Union members will vote on whether to withdraw their labour (= stop working ) .","translation":"اعضای اتحادیه در مورد اینکه آیا کار خود را کنار بگذارند (= توقف کار) رای خواهند داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626646.mp3"},{"sentence":"a government decision to withdraw funding","translation":"تصمیم دولت برای برداشتن بودجه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494164.mp3"}]'::jsonb,3),
('700db37c-23fc-510d-ad08-7f3398671235','9293f094-d170-52ef-bd46-6d5bc7127652',3,'change your mind','نظرت را عوض کن','spoken & written','if you withdraw a threat , offer, request etc, you say that you no longer will do what you said','[ transitive ]',null,'اگر تهدید، پیشنهاد، درخواست و غیره را پس بگیرید، می گویید که دیگر آنچه را که گفته اید انجام نمی دهید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"After much persuasion he agreed to withdraw his resignation.","translation":"پس از متقاعد کردن بسیار، او موافقت کرد که استعفای خود را پس بگیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626660.mp3"}]'::jsonb,1),
('ee2ab25e-eed6-51b7-bf62-52fee3e5f2a6','9293f094-d170-52ef-bd46-6d5bc7127652',4,'say something is not true','بگو چیزی درست نیست','formal','if you withdraw a remark , criticism , statement etc, you say that what you said earlier was completely untrue','[ transitive ]',null,'اگر یک تذکر، انتقاد، بیانیه و غیره را پس بگیرید، می گویید آنچه قبلاً گفته اید کاملاً نادرست است.',array['retract']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He refused to withdraw his remarks and was expelled from the Party.","translation":"او حاضر به پس گرفتن اظهارات خود نشد و از حزب اخراج شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626664.mp3"},{"sentence":"The newspaper has agreed to withdraw its allegations.","translation":"این روزنامه پذیرفته است که ادعاهای خود را پس بگیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494178.mp3"}]'::jsonb,2),
('17a34257-2ae2-5e93-98a3-3d02e3a6849f','9293f094-d170-52ef-bd46-6d5bc7127652',5,'product/service','محصول/خدمت','spoken & written','if a product or service is withdrawn, it is no longer offered for sale or use','[ transitive ]',null,'اگر محصول یا خدماتی پس گرفته شود، دیگر برای فروش یا استفاده ارائه نمی شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The drug has been withdrawn from the market for further tests.","translation":"این دارو برای آزمایشات بیشتر از بازار خارج شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494172.mp3"}]'::jsonb,1),
('713d711d-3275-5407-bfd4-8c6062d90e6e','9293f094-d170-52ef-bd46-6d5bc7127652',6,'leave a place','یک مکان را ترک کنید','spoken & written','if an army withdraws, or if it is withdrawn, it leaves a place','[ intransitive, transitive ]',null,'اگر ارتشی عقب نشینی کند، یا اگر عقب نشینی کند، جایی را ترک می کند',array['pull out']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the USA’s decision to withdraw 40,000 troops from western Europe","translation":"تصمیم ایالات متحده برای خروج 40000 سرباز از غرب اروپا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626673.mp3"},{"sentence":"We withdrew to the garden for a private talk.","translation":"برای صحبت خصوصی به باغ رفتیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494204.mp3"}]'::jsonb,2),
('3b536f49-2896-50b8-a6e9-fe8064c0acf0','9293f094-d170-52ef-bd46-6d5bc7127652',7,'money','پول','spoken & written','to take money out of a bank account','[ transitive ]',null,'برای برداشتن پول از حساب بانکی',array['take out']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’d like to withdraw £500 from my current account.","translation":"من می خواهم 500 پوند از حساب جاری خود برداشت کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494157.mp3"},{"sentence":"Can we stop off at the bank? I need to get some money out .","translation":"آیا می توانیم در بانک توقف کنیم؟ من باید مقداری پول بیرون بیاورم.","audio_url":null}]'::jsonb,2),
('06bc7bf9-d495-54b5-af4f-c0b7cb717064','9293f094-d170-52ef-bd46-6d5bc7127652',8,'move','حرکت کنید','spoken & written','if you withdraw your hand, arm , finger etc from somewhere, you move it from there to where it was before','[ transitive ]',null,'اگر دست، بازو، انگشت و غیره خود را از جایی بیرون بکشید، آن را از آنجا به جایی که قبلا بوده منتقل می‌کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Claudia withdrew her hand from his.","translation":"کلودیا دستش را از دستش بیرون کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626688.mp3"}]'::jsonb,1),
('495d601f-6b63-54c6-8cc8-943054cc0857','9293f094-d170-52ef-bd46-6d5bc7127652',9,'take out','بیرون آوردن','literary','to take an object out from inside something','[ transitive ]',null,'بیرون آوردن یک شی از درون چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She withdrew a document from her briefcase.","translation":"او سندی را از کیفش بیرون کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626695.mp3"}]'::jsonb,1),
('2888e476-0a80-57a4-990f-340f619a76d0','9293f094-d170-52ef-bd46-6d5bc7127652',10,'stop communicating','ارتباط را متوقف کنید','spoken & written','to become quieter, less friendly , and only concerned about your own thoughts','[ intransitive ]',null,'ساکت تر، کمتر صمیمی تر شوید و فقط نگران افکار خود باشید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ralph has withdrawn from the other kids.","translation":"رالف از بچه های دیگر کناره گیری کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494216.mp3"},{"sentence":"Many depressed people just withdraw into themselves.","translation":"بسیاری از افراد افسرده فقط به درون خود فرو می روند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001820159.mp3"}]'::jsonb,2),
