('3152dee1-46d0-50f9-8195-fb867fa27ee7','a544af60-e101-5c6b-ad9f-b9ba100a6536',2,null,null,'spoken & written','a meeting at which people try to improve their skills by discussing their experiences and doing practical exercises',null,null,'جلسه ای که در آن افراد سعی می کنند با بحث در مورد تجربیات خود و انجام تمرین های عملی مهارت های خود را بهبود بخشند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They held a number of music workshops and seminars.","translation":"آنها تعدادی کارگاه و سمینار موسیقی برگزار کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020344.mp3"}]'::jsonb,1),
('86d542f6-64c1-546e-b188-f5c4e0d4eabf','0dc8e842-c1c3-5492-8152-3b5a9cced7a1',1,null,null,'spoken & written','something that is worrying makes you feel anxious or worried',null,null,'نگران‌کننده، دلواپس‌کننده','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The situation is extremely worrying.","translation":"وضعیت به شدت نگران کننده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000500610.mp3"},{"sentence":"This is a worrying development for small businesses.","translation":"این یک تحول نگران کننده برای مشاغل کوچک است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001640827.mp3"},{"sentence":"It’s been a worrying few weeks for us all.","translation":"این چند هفته نگران کننده برای همه ما بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000500615.mp3"}]'::jsonb,3),
('b6ea020f-a99b-5eb6-bbcb-9308d15d49e9','738a7d9c-cd38-5850-9071-82fc9285e41e',1,null,null,'spoken & written','used when talking to someone to show that they are affected by their own action',null,null,'خودت — ضمیر انعکاسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Look at yourself in the mirror.","translation":"به خودت در آینه نگاه کن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837265.mp3"},{"sentence":"Come and warm yourselves by the fire.","translation":"بیایید و خود را در کنار آتش گرم کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837266.mp3"},{"sentence":"Have you hurt yourself?","translation":"به خودت صدمه زدی؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837267.mp3"},{"sentence":"Go and buy yourself an ice cream.","translation":"برو برای خودت بستنی بخر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000486096.mp3"}]'::jsonb,4),
('2618a930-d927-51ce-b054-d84b6fc91aab','738a7d9c-cd38-5850-9071-82fc9285e41e',2,null,null,'spoken & written','used to emphasize ‘you’',null,null,'برای تاکید بر "شما" استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"If you don’t trust me, you’d better go yourself.","translation":"اگر به من اعتماد ندارید، بهتر است خودتان بروید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837272.mp3"},{"sentence":"You yourselves are the guilty ones.","translation":"خود شما مقصرید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837273.mp3"},{"sentence":"It must be true. You told me so yourself.","translation":"باید درست باشد. خودت به من گفتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837274.mp3"},{"sentence":"Most of our customers are people like yourself.","translation":"اکثر مشتریان ما افرادی مانند شما هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837277.mp3"}]'::jsonb,4),
