('c4720cce-d9d9-55c9-a2c6-d1d6322197aa','738a7d9c-cd38-5850-9071-82fc9285e41e',5,null,null,'spoken & written',null,null,'have something (all) to yourself','خودت — ضمیر انعکاسی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('4fdac51b-3c2b-5437-8d0f-a76751e5b650','31f18f2b-e01b-583f-977b-f4d6abaa4475',1,null,null,'spoken & written','to go somewhere with someone',null,null,'همراهی کردن، همراه کسی رفتن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Children under 14 must be accompanied by an adult.","translation":"کودکان زیر 14 سال باید با یک بزرگسال همراه باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000788384.mp3"},{"sentence":"Wherever her husband went, she would accompany him.","translation":"شوهرش هر جا می رفت او را همراهی می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654582.mp3"},{"sentence":"Do you want me to go with you to the station?","translation":"می خواهی با تو به ایستگاه بروم؟","audio_url":null},{"sentence":"She came with me to church.","translation":"او با من به کلیسا آمد.","audio_url":null}]'::jsonb,4),
('43af5514-aaef-56a5-9a13-9cd84307fdae','31f18f2b-e01b-583f-977b-f4d6abaa4475',2,null,null,'spoken & written','to play a musical instrument while someone sings a song or plays the main tune',null,null,'نواختن یک آلات موسیقی در حالی که کسی آهنگی می خواند یا آهنگ اصلی را می نوازد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Daniel wanted Liz to accompany him on violin.","translation":"دنیل از لیز می خواست که او را با ویولن همراهی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654583.mp3"}]'::jsonb,1),
('0b54932f-debf-5fea-ae4b-6e5a2cfcfe0e','31f18f2b-e01b-583f-977b-f4d6abaa4475',3,null,null,'spoken & written','to happen or exist at the same time as something else',null,null,'اتفاق افتادن یا وجود همزمان با چیز دیگری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The disease is accompanied by sneezing and fever.","translation":"این بیماری با عطسه و تب همراه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654584.mp3"}]'::jsonb,1),
('d9ec7266-4041-51ce-ba22-5746568c9808','31f18f2b-e01b-583f-977b-f4d6abaa4475',4,null,null,'spoken & written','if a book, document etc accompanies something, it comes with it',null,null,'اگر کتاب، سند و غیره با چیزی همراه باشد، همراه با آن است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Please see accompanying booklet for instructions.","translation":"لطفاً برای دستورالعمل ها به دفترچه همراه مراجعه کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000788395.mp3"},{"sentence":"Your passport application form should be accompanied by two recent photographs.","translation":"فرم درخواست پاسپورت شما باید با دو عکس اخیر همراه باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654585.mp3"}]'::jsonb,2),
('d65ffacb-94ce-5f07-81f0-f9d954011f1a','eaa5805a-2fc7-5c1b-8bec-8e7b70747779',1,null,null,'spoken & written','a statement in which you admit that something is true or that you have done something wrong','[ countable ]',null,'اعتراف؛ حق ورود، ورودی (پرداختی)',array['confession']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Senator’s admission that he had lied to Congress shocked many Americans.","translation":"اعتراف سناتور مبنی بر اینکه به کنگره دروغ گفته است، بسیاری از آمریکایی ها را شوکه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792984.mp3"},{"sentence":"Silence is often interpreted as an admission of guilt.","translation":"سکوت اغلب به عنوان پذیرش گناه تعبیر می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792987.mp3"},{"sentence":"Reese, by his own admission , lacks the necessary experience.","translation":"ریس، به اعتراف خود، فاقد تجربه لازم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646316.mp3"}]'::jsonb,3),
('2c91086d-b77d-5898-b2c8-b30e1931a255','eaa5805a-2fc7-5c1b-8bec-8e7b70747779',2,null,null,'spoken & written','permission given to someone to enter a building or place, or to become a member of a school, club etc','[ uncountable ]',null,'اجازه ورود به یک ساختمان یا مکان یا عضویت در یک مدرسه، باشگاه و غیره به شخصی داده شده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"No admission after 10 pm.","translation":"بعد از ساعت 10 شب ورود ممنوع","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646320.mp3"},{"sentence":"The young men tried to enter a nightclub but were refused admission .","translation":"مردان جوان سعی کردند وارد یک کلوپ شبانه شوند اما از پذیرش آنها خودداری کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646321.mp3"},{"sentence":"Women gained admission to the club only recently.","translation":"زنان اخیراً به باشگاه راه یافته اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646325.mp3"},{"sentence":"those applying for admission to university","translation":"کسانی که متقاضی پذیرش در دانشگاه هستند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000792997.mp3"}]'::jsonb,4),
('39670a46-5f93-5cb8-a12d-eefeda7ae068','eaa5805a-2fc7-5c1b-8bec-8e7b70747779',3,null,null,'spoken & written',null,null,'admissions','اعتراف؛ حق ورود، ورودی (پرداختی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('056520ba-2095-5f94-a6cd-2600aeb54558','eaa5805a-2fc7-5c1b-8bec-8e7b70747779',4,null,null,'spoken & written','the process of taking someone into a hospital for treatment , tests , or care','[ countable, uncountable ]',null,'فرآیند بردن کسی به بیمارستان برای درمان، آزمایش یا مراقبت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There are 13,000 hospital admissions annually due to playground accidents.","translation":"سالانه 13000 بستری در بیمارستان به دلیل حوادث زمین بازی وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646335.mp3"}]'::jsonb,1),
('5890f34e-ddc0-53cc-88f0-64a47dc00a72','eaa5805a-2fc7-5c1b-8bec-8e7b70747779',5,null,null,'spoken & written','the cost of entrance to a concert , sports event , cinema etc','[ uncountable ]',null,'هزینه ورود به کنسرت، رویداد ورزشی، سینما و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Admission: $10 for adults, $5 for children.","translation":"ورودی: 10 دلار برای بزرگسالان، 5 دلار برای کودکان.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000793016.mp3"},{"sentence":"The cost includes free admission to the casinos.","translation":"هزینه شامل ورود رایگان به کازینو است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646339.mp3"},{"sentence":"The Museum has no admission charge .","translation":"موزه هزینه ورودی ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646343.mp3"}]'::jsonb,3),
('3c63503a-1bd5-599a-93e7-03cfa8e91668','6756ea3a-0059-5cbd-bb39-4c2ca228040d',1,null,null,'spoken & written','something that helps you to be more successful than others, or the state of having this','[ countable, uncountable ]',null,'مزیت، برتری؛ سود، فایده','{}'::text[],'{}'::text[],array['have an advantage ( also enjoy an advantage formal ) Our parents didn’t have all the advantages that we have. Western countries enjoyed considerable advantages in terms of technology.','get/gain an advantage Both teams tried to get an advantage.','give somebody an advantage His height gives him a big advantage.','work to your advantage (= make you have an advantage – often used when this is unexpected ) Sometimes a lack of experience can work to your advantage.','see the advantage (= understand the advantage ) I can see the advantage of living near the station.','a big/great/massive/huge advantage It’s a great advantage to be able to speak some Spanish.','a slight advantage (= a small one ) Karpov enjoyed a slight advantage over his opponent.','an unfair advantage Companies that receive government subsidies have an unfair advantage.','a definite/distinct advantage (= one that you can clearly notice ) Electronic trading has a number of distinct advantages.','a real advantage (= a definite advantage ) The new system has some real advantages.','an added advantage (= an extra advantage ) Candidates with experience in Sales and Marketing would have an added advantage.','a political advantage Republicans have a political advantage in most of those areas.','a military advantage The military advantage had shifted towards the rebels.','a psychological advantage Winning the first game gives you a psychological advantage over your opponent.','the advantages and disadvantages of something the advantages and disadvantages of living in a big city','the advantages outweigh the disadvantages (= the advantages are more valuable ) When it comes down to working from home, you have to decide if the advantages outweigh the disadvantages.']::text[],'[{"sentence":"Her experience meant that she had a big advantage over her opponent.","translation":"تجربه او به این معنی بود که او برتری زیادی نسبت به حریف خود داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000973015.mp3"},{"sentence":"Younger workers tend to be at an advantage (= have an advantage ) when applying for jobs.","translation":"کارگران جوانتر هنگام درخواست شغل در یک مزیت (= دارای مزیت) هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941341.mp3"},{"sentence":"It might be to your advantage (= it might help you ) to take a computer course of some kind.","translation":"ممکن است به نفع شما باشد (= ممکن است به شما کمک کند) که یک نوع دوره کامپیوتر را بگذرانید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646893.mp3"}]'::jsonb,3),
('10746e88-8659-5d5e-98ea-400da063b605','6756ea3a-0059-5cbd-bb39-4c2ca228040d',2,null,null,'spoken & written','a good or useful feature that something has','[ countable, uncountable ]',null,'یک ویژگی خوب یا مفید که چیزی دارد','{}'::text[],'{}'::text[],array['have an advantage ( also enjoy an advantage formal ) Our parents didn’t have all the advantages that we have. Western countries enjoyed considerable advantages in terms of technology.','get/gain an advantage Both teams tried to get an advantage.','give somebody an advantage His height gives him a big advantage.','work to your advantage (= make you have an advantage – often used when this is unexpected ) Sometimes a lack of experience can work to your advantage.','see the advantage (= understand the advantage ) I can see the advantage of living near the station.','a big/great/massive/huge advantage It’s a great advantage to be able to speak some Spanish.','a slight advantage (= a small one ) Karpov enjoyed a slight advantage over his opponent.','an unfair advantage Companies that receive government subsidies have an unfair advantage.','a definite/distinct advantage (= one that you can clearly notice ) Electronic trading has a number of distinct advantages.','a real advantage (= a definite advantage ) The new system has some real advantages.','an added advantage (= an extra advantage ) Candidates with experience in Sales and Marketing would have an added advantage.','a political advantage Republicans have a political advantage in most of those areas.','a military advantage The military advantage had shifted towards the rebels.','a psychological advantage Winning the first game gives you a psychological advantage over your opponent.','the advantages and disadvantages of something the advantages and disadvantages of living in a big city','the advantages outweigh the disadvantages (= the advantages are more valuable ) When it comes down to working from home, you have to decide if the advantages outweigh the disadvantages.']::text[],'[{"sentence":"One of the many advantages of living in New York is that you can eat out at almost any time of day.","translation":"یکی از مزایای متعدد زندگی در نیویورک این است که می توانید تقریباً در هر زمانی از روز بیرون غذا بخورید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000973046.mp3"},{"sentence":"This printer has several advantages over conventional printers.","translation":"این چاپگر نسبت به پرینترهای معمولی مزایای متعددی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000028.mp3"}]'::jsonb,2),
('599ec06b-e240-5012-b862-3e73310e758b','6756ea3a-0059-5cbd-bb39-4c2ca228040d',3,null,null,'spoken & written',null,null,'take advantage of somebody','مزیت، برتری؛ سود، فایده','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('aa5abb80-050d-562b-a40f-724d01f3b255','6756ea3a-0059-5cbd-bb39-4c2ca228040d',4,null,null,'spoken & written',null,null,'take advantage of something (to do something)','مزیت، برتری؛ سود، فایده','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
