('b7582d12-5ec4-55fa-a299-e3671647dc43','479dc884-670c-5ae0-be22-be798f8b5748',1,null,null,'spoken & written','an amount of money that you are given regularly or for a special purpose','[ countable usually singular ]',null,'مقرری، حق‌السهم؛ اضافه‌پرداخت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His father gives him a monthly allowance of £200.","translation":"پدرش ماهیانه 200 پوند به او کمک هزینه می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001655368.mp3"},{"sentence":"Do you get an allowance for clothes?","translation":"آیا برای لباس کمک هزینه می گیرید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001655376.mp3"},{"sentence":"Sales staff get a generous mileage allowance or a company car.","translation":"کارکنان فروش یک کمک هزینه مسافت پیموده شده سخاوتمندانه یا یک ماشین شرکتی دریافت می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776861.mp3"},{"sentence":"If you are entitled to sickness allowance, you must claim it from your employer.","translation":"اگر مستحق دریافت کمک هزینه بیماری هستید، باید آن را از کارفرمای خود مطالبه کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776862.mp3"}]'::jsonb,4),
