('37c6bfc8-1dd8-520c-9f20-19adcc0414a3','5f29fab2-2cfb-5c7d-9696-e24c54a07920',2,null,null,'spoken & written','used to say that people or things do something or exist together at the same time',null,null,'معمولاً می گفت که افراد یا اشیا کاری را همزمان انجام می دهند یا با هم وجود دارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Charles spent a week working alongside the miners.","translation":"چارلز یک هفته در کنار معدنچیان کار کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630518.mp3"},{"sentence":"Organized crime continued to flourish alongside the mainstream economy.","translation":"جرایم سازمان یافته در کنار جریان اصلی اقتصاد به رشد خود ادامه داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841182.mp3"}]'::jsonb,2),
('c5b0b9d7-3116-51f0-a141-9cd7ae2fbb32','5f29fab2-2cfb-5c7d-9696-e24c54a07920',3,null,null,'spoken & written','in comparison with something',null,null,'در مقایسه با چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His achievement may seem small alongside the great triumphs of 20th-century technology.","translation":"ممکن است دستاورد او در کنار پیروزی های بزرگ فناوری قرن بیستم کوچک به نظر برسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841186.mp3"},{"sentence":"Athletics should rank alongside (= be equal to ) soccer and cricket as a major sport.","translation":"دو و میدانی باید در کنار (= برابر با) فوتبال و کریکت به عنوان یک ورزش اصلی رتبه بندی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841187.mp3"}]'::jsonb,2),
('2f289e24-f8dc-56e6-8633-d3a9e2a3bcc2','0152e992-a6c6-53b8-9ce0-e0cae62d3f75',1,null,null,'spoken & written','a special vehicle that is used to take people who are ill or injured to hospital',null,null,'آمبولانس','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the ambulance service","translation":"خدمات آمبولانس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776642.mp3"},{"sentence":"The ambulance crew removed him from the wreckage.","translation":"خدمه آمبولانس او را از لاشه خارج کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630966.mp3"},{"sentence":"the ambulance driver","translation":"راننده آمبولانس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00048.mp3"},{"sentence":"Mike had to be taken by ambulance to hospital.","translation":"مایک مجبور شد با آمبولانس به بیمارستان منتقل شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630967.mp3"},{"sentence":"Do you think we need to call an ambulance (= phone to ask an ambulance to come ) ?","translation":"آیا به نظر شما باید با آمبولانس تماس بگیریم (= تلفن برای درخواست آمبولانس برای آمدن)؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630971.mp3"}]'::jsonb,5),
('b9018ddd-248d-5a4b-a7b8-16c2e3646b9f','74bd451c-a96a-5b79-9e7f-d5d59db8ec5b',1,null,null,'spoken & written','a set of rooms on one floor of a large building, where someone lives',null,null,'آپارتمان، واحد مسکونی','{}'::text[],'{}'::text[],array['a one-bedroom/two-bedroom etc apartment ( also one-bedroomed/two-bedroomed apartment British English ) A tiny one-bedroom apartment was all she could afford.','a studio apartment (= with just one main room, which you use for sleeping, cooking, and eating ) Studio apartments can be a good option for those who want a cheap place in a good location.','a first-floor/second-floor etc apartment We had a fourth-floor apartment, and it was difficult going up and down all those stairs.','a basement apartment (= below the level of the ground ) a dark basement apartment','a penthouse apartment (= on the top floor of a building ) She bought a penthouse apartment in Santa Monica.','a luxury apartment The school has been converted into luxury apartments.','a furnished/unfurnished apartment (= with or without furniture ) a luxurious two-bedroomed unfurnished apartment situated in the heart of town','a holiday apartment British English , a vacation apartment American English We rented a holiday apartment on Mallorca.','live in an apartment He lived in a small apartment on the third floor.','buy/rent an apartment Tom rented an apartment at the top of the building.','share an apartment I’m sharing the apartment with a group of friends.','own an apartment My parents own an apartment in Madrid.','move into/out of an apartment (= start living in a new apartment, or leave an apartment in order to live somewhere else ) They moved into the apartment last Easter.','an apartment building ( also an apartment block British English , apartment house American English ) a five-storey apartment block Our apartment building is the last block on the right, opposite the bank.','an apartment complex (= a group of buildings containing apartments )']::text[],'[{"sentence":"She lives in a small apartment.","translation":"او در یک آپارتمان کوچک زندگی می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647250.mp3"}]'::jsonb,1),
('e9dae81d-bea4-5e21-939f-8de76f77e53c','74bd451c-a96a-5b79-9e7f-d5d59db8ec5b',2,null,null,'spoken & written','a room or set of rooms used by an important person such as a president','[ usually plural ]',null,'یک اتاق یا مجموعه ای از اتاق ها که توسط یک شخص مهم مانند یک رئیس جمهور استفاده می شود','{}'::text[],'{}'::text[],array['a one-bedroom/two-bedroom etc apartment ( also one-bedroomed/two-bedroomed apartment British English ) A tiny one-bedroom apartment was all she could afford.','a studio apartment (= with just one main room, which you use for sleeping, cooking, and eating ) Studio apartments can be a good option for those who want a cheap place in a good location.','a first-floor/second-floor etc apartment We had a fourth-floor apartment, and it was difficult going up and down all those stairs.','a basement apartment (= below the level of the ground ) a dark basement apartment','a penthouse apartment (= on the top floor of a building ) She bought a penthouse apartment in Santa Monica.','a luxury apartment The school has been converted into luxury apartments.','a furnished/unfurnished apartment (= with or without furniture ) a luxurious two-bedroomed unfurnished apartment situated in the heart of town','a holiday apartment British English , a vacation apartment American English We rented a holiday apartment on Mallorca.','live in an apartment He lived in a small apartment on the third floor.','buy/rent an apartment Tom rented an apartment at the top of the building.','share an apartment I’m sharing the apartment with a group of friends.','own an apartment My parents own an apartment in Madrid.','move into/out of an apartment (= start living in a new apartment, or leave an apartment in order to live somewhere else ) They moved into the apartment last Easter.','an apartment building ( also an apartment block British English , apartment house American English ) a five-storey apartment block Our apartment building is the last block on the right, opposite the bank.','an apartment complex (= a group of buildings containing apartments )']::text[],'[{"sentence":"I had never been in the prince’s private apartments before.","translation":"من قبلاً هرگز در آپارتمان شخصی شاهزاده نرفته بودم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647252.mp3"},{"sentence":"the presidential apartments","translation":"آپارتمان های ریاست جمهوری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000983145.mp3"}]'::jsonb,2),
('4c2c82bf-0097-5103-8a1a-e52efee7c4a6','a91c507b-085d-5ee7-adc5-eb1c813ae08b',1,null,null,'spoken & written','to tell someone that you are sorry that you have done something wrong',null,null,'عذرخواهی کردن، پوزش خواستن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m so sorry, I do apologize.","translation":"من خیلی متاسفم، من عذرخواهی می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647288.mp3"},{"sentence":"I think you should apologize to your brother.","translation":"به نظر من باید از برادرت عذرخواهی کنی.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647291.mp3"},{"sentence":"He later apologized for his behaviour.","translation":"او بعداً از رفتار خود عذرخواهی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000943096.mp3"},{"sentence":"I apologize for losing my temper.","translation":"از اینکه اعصابم را از دست دادم عذرخواهی می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647294.mp3"}]'::jsonb,4),
