('5254ddab-179a-5966-a41d-2722a3e44be4','c00afd1a-4ab2-5524-9acf-da5afb33bb20',1,null,null,'spoken & written','an automatic machine is designed to work without needing someone to operate it for each part of a process',null,null,'خودکار، اتوماتیک؛ ناخودآگاه (رفتار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an automatic weapon","translation":"یک سلاح خودکار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928153.mp3"},{"sentence":"an automatic gearbox","translation":"یک گیربکس اتوماتیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001660378.mp3"},{"sentence":"My camera is fully automatic .","translation":"دوربین من تمام اتوماتیک است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001660379.mp3"}]'::jsonb,3),
('7c727683-d692-53d9-bad6-2b3906d47e18','c00afd1a-4ab2-5524-9acf-da5afb33bb20',2,null,null,'spoken & written','something that is automatic always happens as a result of something you have done, especially because of a rule or law',null,null,'چیزی که خودکار است همیشه در نتیجه کاری که شما انجام داده اید اتفاق می افتد، به خصوص به دلیل یک قانون یا قانون','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Littering results in an automatic fine.","translation":"ریختن زباله منجر به جریمه خودکار می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928158.mp3"}]'::jsonb,1),
('52cb9e9e-f162-502e-99ae-7301abaa6f7f','c00afd1a-4ab2-5524-9acf-da5afb33bb20',3,null,null,'spoken & written','done without thinking, especially because you have done the same thing many times before',null,null,'بدون فکر کردن انجام می شود، به خصوص به این دلیل که قبلاً بارها همین کار را انجام داده اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Practise the breathing techniques until they become automatic.","translation":"تکنیک های تنفس را تا زمانی که خودکار شوند تمرین کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928162.mp3"}]'::jsonb,1),
('48f7fe13-f235-5329-9840-d3191b278c42','f0759ec0-3934-583b-b2fb-5a782d75b215',1,null,null,'spoken & written','a weapon that can fire bullets continuously',null,null,'سلاحی که می تواند به طور مداوم گلوله شلیک کند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('5b7beda1-66d3-522b-9086-49ab1b4c0e4c','f0759ec0-3934-583b-b2fb-5a782d75b215',2,null,null,'spoken & written','a car with a system of gear s that operate themselves without the driver needing to change them',null,null,'خودرویی با سیستم دنده‌هایی که خودشان بدون نیاز به تعویض راننده کار می‌کنند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('56d64c4d-0828-559f-8198-a5d7b9243127','040b8120-a723-5a39-820c-56cb65346308',1,null,null,'spoken & written','something that is available is able to be used or can easily be bought or found',null,null,'در دسترس، موجود؛ آزاد (شخص)','{}'::text[],'{}'::text[],array['become available Luckily a house soon became available for us.','make something available With the Internet it is possible to make learning available wherever it is needed.','be easily/readily/freely available (= easy to get ) The material used was cheap and readily available.','be widely available (= available in many places ) Organic food is now widely available.','the best available We use the best available technology.','the only available something One small tree was the only available protection from the sun.','the nearest available something Ruth sat down in the nearest available armchair.','every available something You should practise speaking the language at every available opportunity.']::text[],'[{"sentence":"Tickets are available from the box office.","translation":"بلیط از گیشه موجود است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928402.mp3"},{"sentence":"Not enough data is available to scientists.","translation":"داده های کافی در دسترس دانشمندان نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928409.mp3"},{"sentence":"Funds are available to assist teachers who want to attend the conference.","translation":"بودجه برای کمک به معلمانی که می خواهند در کنفرانس شرکت کنند در دسترس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644397.mp3"},{"sentence":"No figures are available for the number of goods sold.","translation":"هیچ رقمی برای تعداد کالاهای فروخته شده در دسترس نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928406.mp3"},{"sentence":"There are plenty of jobs available in the area.","translation":"مشاغل زیادی در این منطقه وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644400.mp3"},{"sentence":"Parking is readily available near the station entrance.","translation":"پارکینگ در نزدیکی ورودی ایستگاه به راحتی در دسترس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928413.mp3"},{"sentence":"Meetings were held to update employees as soon as new information became available .","translation":"به محض اینکه اطلاعات جدید در دسترس قرار گرفت، جلساتی برای به روز رسانی کارکنان برگزار شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644401.mp3"},{"sentence":"Further building can continue when money is made available .","translation":"ساخت و ساز بیشتر می تواند ادامه یابد زمانی که پول در دسترس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644405.mp3"},{"sentence":"Every available space on the wall was covered in pictures.","translation":"تمام فضای موجود روی دیوار با تصاویر پوشانده شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644409.mp3"},{"sentence":"His new album is out now.","translation":"آلبوم جدید او هم اکنون منتشر شده است.","audio_url":null}]'::jsonb,10),
('ab3986fa-a51b-5166-8e92-28cce099f05a','040b8120-a723-5a39-820c-56cb65346308',2,null,null,'spoken & written','someone who is available is not busy and has enough time to talk to you','[ not before noun ]',null,'کسی که در دسترس است سرش شلوغ نیست و زمان کافی برای صحبت کردن با شما دارد','{}'::text[],'{}'::text[],array['become available Luckily a house soon became available for us.','make something available With the Internet it is possible to make learning available wherever it is needed.','be easily/readily/freely available (= easy to get ) The material used was cheap and readily available.','be widely available (= available in many places ) Organic food is now widely available.','the best available We use the best available technology.','the only available something One small tree was the only available protection from the sun.','the nearest available something Ruth sat down in the nearest available armchair.','every available something You should practise speaking the language at every available opportunity.']::text[],'[{"sentence":"Collins was not available for comment on Thursday night.","translation":"کالینز پنجشنبه شب برای اظهار نظر در دسترس نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000928422.mp3"}]'::jsonb,1),
('bfc27085-0901-5f40-9407-86afeda661ae','040b8120-a723-5a39-820c-56cb65346308',3,null,null,'spoken & written','someone who is available does not have a wife , boyfriend etc, and therefore may want to start a new romantic relationship with someone else',null,null,'کسی که در دسترس است همسر، دوست پسر و غیره ندارد، بنابراین ممکن است بخواهد یک رابطه عاشقانه جدید با شخص دیگری شروع کند.','{}'::text[],'{}'::text[],array['become available Luckily a house soon became available for us.','make something available With the Internet it is possible to make learning available wherever it is needed.','be easily/readily/freely available (= easy to get ) The material used was cheap and readily available.','be widely available (= available in many places ) Organic food is now widely available.','the best available We use the best available technology.','the only available something One small tree was the only available protection from the sun.','the nearest available something Ruth sat down in the nearest available armchair.','every available something You should practise speaking the language at every available opportunity.']::text[],'[]'::jsonb,0),
('5a8097fa-92ea-5b12-b327-56c5b4c58b60','868d50f3-96a7-5ff5-b6a4-86315d0af559',1,null,null,'spoken & written','knowledge or understanding of a particular subject or situation',null,null,'آگاهی، شناخت، توجه به','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Health officials have tried to raise awareness (= improve people’s knowledge ) about AIDS.","translation":"مقامات بهداشتی تلاش کرده اند تا آگاهی (= بهبود دانش مردم) را در مورد ایدز افزایش دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644568.mp3"}]'::jsonb,1),
