('92782323-9dce-5073-9f5b-3ad8acb91208','6f4c62f7-e8f1-568b-86a7-fb53407ad03d',1,null,null,'spoken & written','in the direction that is behind you',null,null,'به عقب، رو به عقب؛ وارونه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Hannah took a step backward.","translation":"هانا یک قدم به عقب رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001731676.mp3"},{"sentence":"She pushed me and I fell backwards into the chair.","translation":"او مرا هل داد و من به پشت روی صندلی افتادم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001731677.mp3"}]'::jsonb,2),
('bc2c89fa-ee92-5124-9f1d-c4637f816223','6f4c62f7-e8f1-568b-86a7-fb53407ad03d',2,null,null,'spoken & written','towards the beginning or the past',null,null,'به سمت آغاز یا گذشته','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Count backwards from 100.","translation":"از 100 معکوس بشمارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001731678.mp3"}]'::jsonb,1),
('e9e5f003-86fe-5178-afd1-18993d5322ae','6f4c62f7-e8f1-568b-86a7-fb53407ad03d',3,null,null,'spoken & written','with the back part in front',null,null,'با قسمت پشت در جلو','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Your T-shirt is on backwards.","translation":"تی شرت شما رو به عقب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001731679.mp3"}]'::jsonb,1),
('eac96d96-36d1-5cb6-85e3-dd9564ae0ee2','6f4c62f7-e8f1-568b-86a7-fb53407ad03d',4,null,null,'spoken & written','towards a worse state',null,null,'به سمت وضعیت بدتر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The new measures are seen by some as a major step backwards.","translation":"برخی اقدامات جدید را یک گام بزرگ به عقب می دانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000999909.mp3"}]'::jsonb,1),
