('d658b07c-e6f0-5e2e-beab-2a17d7b5b41b','a85ade0c-f106-515c-a097-99a69c60c976',1,null,null,'spoken','used to emphasize the most important reason or fact about something, or a simple explanation of something','[ sentence adverb ]',null,'به‌طور کلی، اساساً؛ در اصل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Basically, I’m just lazy.","translation":"اصولاً من فقط تنبل هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001003453.mp3"},{"sentence":"Well, basically, it’s a matter of filling in a few forms.","translation":"خب، اساساً، این موضوع پر کردن چند فرم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001003454.mp3"},{"sentence":"I used to see him every night, basically.","translation":"اساساً هر شب او را می دیدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001658771.mp3"}]'::jsonb,3),
('748399bf-3a8c-5199-947b-6c7ac97a81d6','a85ade0c-f106-515c-a097-99a69c60c976',2,null,null,'spoken & written','in the main or most important ways, without considering additional details or differences',null,null,'به روش های اصلی یا مهم، بدون در نظر گرفتن جزئیات یا تفاوت های اضافی',array['fundamentally']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"All cheeses are made in basically the same way.","translation":"همه پنیرها اساساً به یک روش درست می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001003458.mp3"},{"sentence":"I believe that human beings are basically good.","translation":"من معتقدم که انسان اساساً خوب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001658772.mp3"},{"sentence":"Basically, he hadn’t changed at all.","translation":"اصولاً او اصلاً تغییر نکرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001003459.mp3"}]'::jsonb,3),
('daba697a-4b1e-57f2-919a-45a98edcf4b0','7a130e54-9fd0-5bd3-9eb7-872d860c947f',1,null,null,'spoken & written','someone or something that is beautiful is extremely attractive to look at',null,null,'زیبا، قشنگ؛ فوق‌العاده','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She was even more beautiful than I had remembered.","translation":"او حتی زیباتر از آن چیزی بود که من به یاد داشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000911121.mp3"},{"sentence":"a beautiful bunch of flowers","translation":"یک دسته گل زیبا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000911122.mp3"}]'::jsonb,2),
('514cf6c2-96f8-5040-aae6-ea48f4f462d7','7a130e54-9fd0-5bd3-9eb7-872d860c947f',2,null,null,'spoken & written','very good or giving you great pleasure',null,null,'بسیار خوب است یا به شما لذت زیادی می دهد',array['lovely']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"beautiful music","translation":"موسیقی زیبا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001651192.mp3"},{"sentence":"What a beautiful shot!","translation":"چه شات زیبایی!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000911127.mp3"},{"sentence":"The weather was beautiful.","translation":"هوا قشنگ بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000911128.mp3"}]'::jsonb,3),
('dae096bf-ce42-5bce-93cc-077f2357518f','6e2cca83-4807-50ac-a3b0-8f123f66a52f',1,null,null,'spoken & written','the start or first part of an event , story , period of time etc',null,null,'آغاز، ابتدا، شروع','{}'::text[],'{}'::text[],array['a new beginning The country needed a new government and a new beginning.','mark the beginning of something ( also signal/herald the beginning of something ) (= show that something is starting to happen ) This event marked the beginning of a ten-year worldwide depression.','see the beginning of something (= be the time when something important starts to happen ) The 1970s saw the beginning of a technological revolution.','right at/from the beginning (= used for emphasis ) That’s what I suggested right at the beginning.','at/from the very beginning (= used for emphasis ) He had been lying to me from the very beginning.','start at the beginning (= start a story or activity at the first part ) Just start at the beginning and tell us exactly what happened.','from beginning to end The whole project was full of problems from beginning to end.','something is just/only the beginning (= used to emphasize that many more things will happen ) Signing the contract is just the beginning of a long process.']::text[],'[{"sentence":"She’s been here since the beginning of the year.","translation":"او از اول سال اینجا بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891814.mp3"},{"sentence":"There’s a short poem at the beginning of every chapter.","translation":"در ابتدای هر فصل یک شعر کوتاه وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001674742.mp3"},{"sentence":"From the beginning of my career as a journalist, I’ve been writing about gender issues.","translation":"از ابتدای کارم به عنوان روزنامه نگار، درباره مسائل جنسیتی می نوشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891817.mp3"},{"sentence":"I thought he loved me; perhaps he did in the beginning .","translation":"فکر می کردم او مرا دوست دارد؛ شاید او در آغاز .","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001674745.mp3"},{"sentence":"That chance meeting marked the beginning of a long and happy relationship.","translation":"آن ملاقات اتفاقی آغاز یک رابطه طولانی و شاد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001674749.mp3"},{"sentence":"This is just the beginning of a new and different life for you.","translation":"این فقط شروع یک زندگی جدید و متفاوت برای شماست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891818.mp3"},{"sentence":"I said he would cause trouble, right from the beginning .","translation":"گفتم از همان اول دردسر ایجاد می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000911932.mp3"},{"sentence":"I opposed it from the very beginning .","translation":"من از همون اول مخالفت کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891822.mp3"},{"sentence":"The whole trip was a disaster from beginning to end .","translation":"کل سفر از ابتدا تا انتها یک فاجعه بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000911935.mp3"},{"sentence":"I feel like I’ve been offered a new beginning .","translation":"احساس می کنم شروع جدیدی به من پیشنهاد شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891826.mp3"},{"sentence":"Could we start at the beginning ? Tell me where you first met him.","translation":"آیا می توانیم از ابتدا شروع کنیم؟ به من بگو اولین بار کجا او را دیدی.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891830.mp3"}]'::jsonb,11),
('894c3e77-a93c-5430-99c3-2f8b2e68da98','6e2cca83-4807-50ac-a3b0-8f123f66a52f',2,null,null,'spoken & written',null,null,'beginnings','آغاز، ابتدا، شروع','{}'::text[],'{}'::text[],array['a new beginning The country needed a new government and a new beginning.','mark the beginning of something ( also signal/herald the beginning of something ) (= show that something is starting to happen ) This event marked the beginning of a ten-year worldwide depression.','see the beginning of something (= be the time when something important starts to happen ) The 1970s saw the beginning of a technological revolution.','right at/from the beginning (= used for emphasis ) That’s what I suggested right at the beginning.','at/from the very beginning (= used for emphasis ) He had been lying to me from the very beginning.','start at the beginning (= start a story or activity at the first part ) Just start at the beginning and tell us exactly what happened.','from beginning to end The whole project was full of problems from beginning to end.','something is just/only the beginning (= used to emphasize that many more things will happen ) Signing the contract is just the beginning of a long process.']::text[],'[]'::jsonb,0),
('cb713c3b-459a-52d0-a5e5-0f4f2b69ef7d','6e2cca83-4807-50ac-a3b0-8f123f66a52f',3,null,null,'spoken & written',null,null,'the beginning of the end','آغاز، ابتدا، شروع','{}'::text[],'{}'::text[],array['a new beginning The country needed a new government and a new beginning.','mark the beginning of something ( also signal/herald the beginning of something ) (= show that something is starting to happen ) This event marked the beginning of a ten-year worldwide depression.','see the beginning of something (= be the time when something important starts to happen ) The 1970s saw the beginning of a technological revolution.','right at/from the beginning (= used for emphasis ) That’s what I suggested right at the beginning.','at/from the very beginning (= used for emphasis ) He had been lying to me from the very beginning.','start at the beginning (= start a story or activity at the first part ) Just start at the beginning and tell us exactly what happened.','from beginning to end The whole project was full of problems from beginning to end.','something is just/only the beginning (= used to emphasize that many more things will happen ) Signing the contract is just the beginning of a long process.']::text[],'[]'::jsonb,0),
('2c498d80-ed94-5236-a077-ff64a2b57924','09570eb7-0a73-5412-9abc-f91fa7682b25',1,null,null,'spoken & written','the things that a person or animal does',null,null,'رفتار، کردار؛ عملکرد','{}'::text[],'{}'::text[],array['good/bad The boys were suspended from school for bad behaviour. His good behaviour did not last long.','normal/abnormal They thought their son’s behaviour was perfectly normal. Were there any signs of abnormal behaviour?','aggressive/violent/threatening His behavior became increasingly violent.','antisocial antisocial behaviour such as spitting and swearing in public','acceptable/unacceptable This sort of behavior is completely unacceptable.','appropriate/inappropriate formal (= suitable/not suitable for that situation ) Within the official school framework there are penalties for inappropriate behaviour.','human/animal behaviour the scientific study of human behaviour detailed observations of animal behaviour','criminal behaviour There are many theories as to what causes criminal behaviour.','sexual behaviour a survey of human sexual behaviour','behaviour problems She teaches children with behaviour problems.','standards of behaviour declining standards of behaviour among young people It’s a parent’s job to instruct children in acceptable standards of behaviour.','a pattern of behaviour Different patterns of behaviour exist in different cultures.','change your behaviour ( also modify your behaviour formal ) He has no reason to change his behaviour.','influence somebody’s behaviour The genes we inherit influence our behaviour.']::text[],'[{"sentence":"It is important to reward good behaviour.","translation":"مهم است که به رفتار خوب پاداش دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891852.mp3"},{"sentence":"She complained of her boss’s inappropriate behavior towards her.","translation":"او از رفتار نامناسب رئیسش با او شکایت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891862.mp3"},{"sentence":"the effects of alcohol on human behaviour","translation":"اثرات الکل بر رفتار انسان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891871.mp3"}]'::jsonb,3),
('f97541cd-61c9-52a5-a405-c03051a01a8a','09570eb7-0a73-5412-9abc-f91fa7682b25',2,null,null,'spoken & written',null,null,'be on your best behaviour','رفتار، کردار؛ عملکرد','{}'::text[],'{}'::text[],array['good/bad The boys were suspended from school for bad behaviour. His good behaviour did not last long.','normal/abnormal They thought their son’s behaviour was perfectly normal. Were there any signs of abnormal behaviour?','aggressive/violent/threatening His behavior became increasingly violent.','antisocial antisocial behaviour such as spitting and swearing in public','acceptable/unacceptable This sort of behavior is completely unacceptable.','appropriate/inappropriate formal (= suitable/not suitable for that situation ) Within the official school framework there are penalties for inappropriate behaviour.','human/animal behaviour the scientific study of human behaviour detailed observations of animal behaviour','criminal behaviour There are many theories as to what causes criminal behaviour.','sexual behaviour a survey of human sexual behaviour','behaviour problems She teaches children with behaviour problems.','standards of behaviour declining standards of behaviour among young people It’s a parent’s job to instruct children in acceptable standards of behaviour.','a pattern of behaviour Different patterns of behaviour exist in different cultures.','change your behaviour ( also modify your behaviour formal ) He has no reason to change his behaviour.','influence somebody’s behaviour The genes we inherit influence our behaviour.']::text[],'[]'::jsonb,0),
