('b6ea795d-84f6-5404-bc84-1c04fa847bd2','6d332ce0-7c80-5023-bd89-c254f438db07',4,'successful','موفق','spoken & written','very successful',null,null,'بسیار موفق','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He had a long and brilliant career .","translation":"او حرفه ای طولانی و درخشان داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001677588.mp3"},{"sentence":"The project was a brilliant success .","translation":"این پروژه یک موفقیت درخشان بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001677592.mp3"}]'::jsonb,2),
('99f1d396-583a-5d23-903e-9dd95d24a9c7','12f562af-b514-533c-b949-1380ee21dc48',1,null,null,'spoken & written','to find out how much something will cost , how long something will take etc, by using numbers',null,null,'محاسبه کردن، حساب کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"These instruments calculate distances precisely.","translation":"این ابزارها فواصل را دقیقا محاسبه می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001679271.mp3"},{"sentence":"I’m trying to calculate how much paint we need.","translation":"من سعی می کنم محاسبه کنم که چقدر رنگ نیاز داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000891212.mp3"},{"sentence":"Sally calculated that she’d have about £100 left.","translation":"سالی محاسبه کرد که حدود 100 پوند برایش باقی مانده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000891215.mp3"},{"sentence":"Rates are calculated on an hourly basis.","translation":"نرخ ها به صورت ساعتی محاسبه می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001679278.mp3"},{"sentence":"We still haven’t worked out how much it’s all going to cost.","translation":"ما هنوز مشخص نکرده‌ایم که این همه هزینه چقدر است.","audio_url":null},{"sentence":"It is calculated that over $16 billion has been spent on the project.","translation":"برآورد می شود که بالغ بر 16 میلیارد دلار برای این پروژه هزینه شده است.","audio_url":null}]'::jsonb,6),
('dadf5c65-97d5-57ca-a085-9de36ac02c55','12f562af-b514-533c-b949-1380ee21dc48',2,null,null,'spoken & written','to guess something using as many facts as you can find',null,null,'حدس زدن چیزی با استفاده از حقایق زیادی که می توانید پیدا کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Researchers calculated that this group was at a higher risk of heart disease.","translation":"محققان محاسبه کردند که این گروه در معرض خطر بیشتری برای بیماری قلبی قرار دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001679281.mp3"},{"sentence":"It’s difficult to calculate what effect all these changes will have on the company.","translation":"محاسبه اینکه همه این تغییرات چه تأثیری بر شرکت خواهند داشت دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000891219.mp3"}]'::jsonb,2),
