('88ef937e-076a-53aa-bccc-927e14e4e233','7c77aaf9-8253-5839-ac90-febbd04b3d8b',1,null,null,'spoken & written','without any doubt',null,null,'قطعاً، یقیناً؛ البته',array['definitely']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I certainly never expected to become a writer.","translation":"مطمئناً هرگز انتظار نداشتم نویسنده شوم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659214.mp3"},{"sentence":"They’re certainly not mine.","translation":"آنها مطمئناً مال من نیستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659215.mp3"},{"sentence":"It is certainly true that there are more courses on offer.","translation":"مطمئناً درست است که دوره های بیشتری ارائه می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659218.mp3"},{"sentence":"The girl was almost certainly murdered.","translation":"این دختر تقریباً به قتل رسیده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659219.mp3"},{"sentence":"‘Not smoking has made a real difference.’ ‘It most certainly has.’","translation":"\"سیگار نکشیدن تفاوت واقعی ایجاد کرده است.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000878996.mp3"}]'::jsonb,5),
('0d005fd5-7e28-5ba5-95b6-9d2e24baa38a','7c77aaf9-8253-5839-ac90-febbd04b3d8b',2,null,null,'spoken','used to agree or give your permission',null,null,'برای موافقت یا اجازه شما استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘I’d like a beer, please.’ ‘Certainly, sir.’","translation":"\"من یک آبجو می خواهم، لطفا.\" \"مطمئنا، قربان.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000879008.mp3"},{"sentence":"‘Can I come along?’ ‘Certainly.’","translation":"\"میتونم بیام؟\" \"مطمئنا.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000879009.mp3"}]'::jsonb,2),
('1e6e07ec-7b66-5c8e-adb6-a8b75136489c','7c77aaf9-8253-5839-ac90-febbd04b3d8b',3,null,null,'spoken & written',null,null,'certainly not','قطعاً، یقیناً؛ البته','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('9b0ac92f-aae2-585a-a81b-bbf15ddcfde4','6bf61dad-c7a2-511a-bf4a-a09a05f5e3d7',1,'something difficult','چیزی سخت','spoken & written','something that tests strength , skill , or ability , especially in a way that is interesting','[ countable, uncountable ]',null,'چالش، آزمون (توانایی)؛ به‌چالش‌کشیدن','{}'::text[],'{}'::text[],array['meet a challenge (= deal with one ) Here are a few tips to help you meet the challenges of university life.','face a challenge (= have to deal with one ) The company still faces some challenges.','accept a challenge (= try to deal with one ) He was ready to accept new challenges.','take on a challenge (= accept one ) The new headteacher has taken on the challenge of improving the school.','present/pose a challenge (= be a difficult one ) These changes pose a real challenge to farmers.','provide a challenge (= be an interesting one ) Her new job provided a real challenge.','rise to a challenge (= deal successfully with it ) It was a difficult project but we rose to the challenge.','love/enjoy/relish a challenge Children enjoy a challenge so the work should not be too easy.','a big/major/huge/tremendous challenge Building the tunnel presented a major challenge to engineers.','a serious challenge At the moment we are facing a serious environmental challenge.','a real challenge (= a difficult one ) On Monday, Sharapova faced her first real challenge of the tournament.','a formidable/daunting/tough challenge (= a very difficult one ) How to deal with waste is a daunting challenge for the west.','the biggest challenge of something This could be the biggest challenge of his career.','an intellectual/physical/technical etc challenge I love the physical challenge of climbing.']::text[],'[{"sentence":"The company is ready to meet the challenges of the next few years.","translation":"این شرکت آماده مقابله با چالش های چند سال آینده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687422.mp3"},{"sentence":"I relish the challenge of rebuilding the club.","translation":"من از چالش بازسازی باشگاه لذت می برم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687425.mp3"},{"sentence":"Martins now faces the biggest challenge of his career.","translation":"مارتینز اکنون با بزرگترین چالش دوران حرفه ای خود روبرو است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069043.mp3"},{"sentence":"a new and vibrant initiative to meet the challenge of the 21st century","translation":"یک ابتکار جدید و پر جنب و جوش برای رویارویی با چالش قرن بیست و یکم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069047.mp3"},{"sentence":"the intellectual challenge of postgraduate research","translation":"چالش فکری تحقیقات تحصیلات تکمیلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001789721.mp3"}]'::jsonb,5),
('b4ac88d7-1354-5a22-ae1c-4c6daab1341e','6bf61dad-c7a2-511a-bf4a-a09a05f5e3d7',2,'question something','چیزی را زیر سوال ببر','spoken & written','when someone refuses to accept that someone or something is right and legal','[ countable ]',null,'وقتی کسی قبول نمی کند که کسی یا چیزی درست و قانونی است','{}'::text[],'{}'::text[],array['meet a challenge (= deal with one ) Here are a few tips to help you meet the challenges of university life.','face a challenge (= have to deal with one ) The company still faces some challenges.','accept a challenge (= try to deal with one ) He was ready to accept new challenges.','take on a challenge (= accept one ) The new headteacher has taken on the challenge of improving the school.','present/pose a challenge (= be a difficult one ) These changes pose a real challenge to farmers.','provide a challenge (= be an interesting one ) Her new job provided a real challenge.','rise to a challenge (= deal successfully with it ) It was a difficult project but we rose to the challenge.','love/enjoy/relish a challenge Children enjoy a challenge so the work should not be too easy.','a big/major/huge/tremendous challenge Building the tunnel presented a major challenge to engineers.','a serious challenge At the moment we are facing a serious environmental challenge.','a real challenge (= a difficult one ) On Monday, Sharapova faced her first real challenge of the tournament.','a formidable/daunting/tough challenge (= a very difficult one ) How to deal with waste is a daunting challenge for the west.','the biggest challenge of something This could be the biggest challenge of his career.','an intellectual/physical/technical etc challenge I love the physical challenge of climbing.']::text[],'[{"sentence":"a direct challenge to the Governor’s authority","translation":"یک چالش مستقیم با اختیارات فرماندار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069056.mp3"},{"sentence":"The president faces a strong challenge from nationalists.","translation":"رئیس جمهور با چالش شدید ملی گرایان مواجه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687429.mp3"},{"sentence":"The strike represented a serious challenge to the government.","translation":"این اعتصاب یک چالش جدی برای دولت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687432.mp3"},{"sentence":"They decided to mount a legal challenge to the decision.","translation":"آنها تصمیم گرفتند به این تصمیم اعتراض قانونی کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687435.mp3"}]'::jsonb,4),
('c04c1ae4-c06f-5c7d-b3d1-354a3d05c221','6bf61dad-c7a2-511a-bf4a-a09a05f5e3d7',3,'competition','رقابت','spoken & written','when someone tries to win something or invites someone to try to beat them in a fight , competition etc','[ countable ]',null,'وقتی کسی سعی می کند چیزی را برنده شود یا کسی را دعوت می کند تا در یک دعوا، رقابت و غیره او را شکست دهد','{}'::text[],'{}'::text[],array['meet a challenge (= deal with one ) Here are a few tips to help you meet the challenges of university life.','face a challenge (= have to deal with one ) The company still faces some challenges.','accept a challenge (= try to deal with one ) He was ready to accept new challenges.','take on a challenge (= accept one ) The new headteacher has taken on the challenge of improving the school.','present/pose a challenge (= be a difficult one ) These changes pose a real challenge to farmers.','provide a challenge (= be an interesting one ) Her new job provided a real challenge.','rise to a challenge (= deal successfully with it ) It was a difficult project but we rose to the challenge.','love/enjoy/relish a challenge Children enjoy a challenge so the work should not be too easy.','a big/major/huge/tremendous challenge Building the tunnel presented a major challenge to engineers.','a serious challenge At the moment we are facing a serious environmental challenge.','a real challenge (= a difficult one ) On Monday, Sharapova faced her first real challenge of the tournament.','a formidable/daunting/tough challenge (= a very difficult one ) How to deal with waste is a daunting challenge for the west.','the biggest challenge of something This could be the biggest challenge of his career.','an intellectual/physical/technical etc challenge I love the physical challenge of climbing.']::text[],'[{"sentence":"They are ready to mount a challenge for the championship.","translation":"آنها آماده هستند تا چالشی را برای قهرمانی ایجاد کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069063.mp3"},{"sentence":"They threw down the challenge that he couldn’t wash 40 cars in one hour (= invited him to try to do it ) .","translation":"آنها این چالش را کنار گذاشتند که او نمی تواند 40 ماشین را در یک ساعت بشوید (= از او دعوت کردند که این کار را انجام دهد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687444.mp3"},{"sentence":"The prime minister narrowly avoided a leadership challenge last year.","translation":"نخست وزیر سال گذشته به سختی از چالش رهبری اجتناب کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001789725.mp3"}]'::jsonb,3),
('e842c39a-7bd7-55a3-a7be-cd97a9f77117','6bf61dad-c7a2-511a-bf4a-a09a05f5e3d7',4,'stop','توقف','spoken & written','a demand from someone such as a guard to stop and give proof of who you are, and an explanation of what you are doing','[ countable ]',null,'درخواست از شخصی مانند نگهبان برای توقف و ارائه مدرکی که شما کی هستید و توضیحی در مورد کاری که انجام می دهید','{}'::text[],'{}'::text[],array['meet a challenge (= deal with one ) Here are a few tips to help you meet the challenges of university life.','face a challenge (= have to deal with one ) The company still faces some challenges.','accept a challenge (= try to deal with one ) He was ready to accept new challenges.','take on a challenge (= accept one ) The new headteacher has taken on the challenge of improving the school.','present/pose a challenge (= be a difficult one ) These changes pose a real challenge to farmers.','provide a challenge (= be an interesting one ) Her new job provided a real challenge.','rise to a challenge (= deal successfully with it ) It was a difficult project but we rose to the challenge.','love/enjoy/relish a challenge Children enjoy a challenge so the work should not be too easy.','a big/major/huge/tremendous challenge Building the tunnel presented a major challenge to engineers.','a serious challenge At the moment we are facing a serious environmental challenge.','a real challenge (= a difficult one ) On Monday, Sharapova faced her first real challenge of the tournament.','a formidable/daunting/tough challenge (= a very difficult one ) How to deal with waste is a daunting challenge for the west.','the biggest challenge of something This could be the biggest challenge of his career.','an intellectual/physical/technical etc challenge I love the physical challenge of climbing.']::text[],'[]'::jsonb,0),
('33af86c2-e897-540d-992d-fbf442b511ae','6bf61dad-c7a2-511a-bf4a-a09a05f5e3d7',5,'in law','در قانون','law','a statement made before the start of a court case that a juror is not acceptable','[ countable ]',null,'بیانیه ای که قبل از شروع یک پرونده دادگاه ارائه می شود مبنی بر اینکه هیئت منصفه قابل قبول نیست','{}'::text[],'{}'::text[],array['meet a challenge (= deal with one ) Here are a few tips to help you meet the challenges of university life.','face a challenge (= have to deal with one ) The company still faces some challenges.','accept a challenge (= try to deal with one ) He was ready to accept new challenges.','take on a challenge (= accept one ) The new headteacher has taken on the challenge of improving the school.','present/pose a challenge (= be a difficult one ) These changes pose a real challenge to farmers.','provide a challenge (= be an interesting one ) Her new job provided a real challenge.','rise to a challenge (= deal successfully with it ) It was a difficult project but we rose to the challenge.','love/enjoy/relish a challenge Children enjoy a challenge so the work should not be too easy.','a big/major/huge/tremendous challenge Building the tunnel presented a major challenge to engineers.','a serious challenge At the moment we are facing a serious environmental challenge.','a real challenge (= a difficult one ) On Monday, Sharapova faced her first real challenge of the tournament.','a formidable/daunting/tough challenge (= a very difficult one ) How to deal with waste is a daunting challenge for the west.','the biggest challenge of something This could be the biggest challenge of his career.','an intellectual/physical/technical etc challenge I love the physical challenge of climbing.']::text[],'[]'::jsonb,0),
('6b80cee2-d98e-5004-9247-42d121d02a03','5a5e811d-f95e-5c6a-b46e-a3b97ae87485',1,'question something','چیزی را زیر سوال ببر','spoken & written','to refuse to accept that something is right, fair , or legal',null,null,'به چالش کشیدن، زیر سؤال بردن؛ دعوت به مسابقه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a boy with a reputation for challenging the authority of his teachers","translation":"پسری که به به چالش کشیدن اقتدار معلمانش شهرت دارد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687460.mp3"},{"sentence":"Viewpoints such as these are strongly challenged by environmentalists.","translation":"دیدگاه هایی از این دست به شدت توسط دوستداران محیط زیست به چالش کشیده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687468.mp3"},{"sentence":"They went to the High Court to challenge the decision .","translation":"آنها برای اعتراض به این تصمیم به دادگاه عالی رفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687469.mp3"},{"sentence":"I challenge Dr. Carver to deny his involvement!","translation":"من دکتر کارور را به چالش می کشم تا دخالت خود را انکار کند!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069097.mp3"}]'::jsonb,4),
('f3b740d6-5e3a-5289-a381-27d42296c3ad','5a5e811d-f95e-5c6a-b46e-a3b97ae87485',2,'competition','رقابت','spoken & written','to invite someone to compete or fight against you, or to try to win something',null,null,'دعوت کردن از کسی برای رقابت یا مبارزه با شما، یا تلاش برای برنده شدن در چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"After lunch, Carey challenged me to a game of tennis.","translation":"بعد از ناهار، کری من را به یک بازی تنیس دعوت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069103.mp3"},{"sentence":"Liverpool are challenging for the title (= in a position where they could win ) .","translation":"لیورپول برای کسب عنوان (= در موقعیتی که می تواند برنده شود) چالش برانگیز است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001687482.mp3"}]'::jsonb,2),
('7e11402f-d350-56ed-899a-bb6615b36983','5a5e811d-f95e-5c6a-b46e-a3b97ae87485',3,'something difficult','چیزی سخت','spoken & written','to test the skills or abilities of someone or something',null,null,'برای آزمایش مهارت ها یا توانایی های کسی یا چیزی',array['stimulate']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m really at my best when I’m challenged.","translation":"وقتی به چالش کشیده می شوم واقعا در بهترین حالتم هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069114.mp3"},{"sentence":"Every teacher ought to be challenging kids to think about current issues.","translation":"هر معلمی باید بچه ها را به چالش بکشد تا در مورد مسائل جاری فکر کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069117.mp3"}]'::jsonb,2),
('c91a3ad6-07c8-50fe-b4c4-801780d16ad7','5a5e811d-f95e-5c6a-b46e-a3b97ae87485',4,'stop somebody','کسی را متوقف کنید','spoken & written','to stop someone and demand proof of who they are, and an explanation of what they are doing',null,null,'برای متوقف کردن کسی و درخواست اثبات اینکه او کیست و توضیحی درباره کاری که انجام می دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We were challenged by the security guard at the gate.","translation":"ما توسط نگهبان در دروازه به چالش کشیده شدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001069121.mp3"}]'::jsonb,1),
('5ae1b6bb-9d6c-5a77-a056-9b30042b40b9','5a5e811d-f95e-5c6a-b46e-a3b97ae87485',5,'in law','در قانون','law','to state before the start of a court case that a juror is not acceptable',null,null,'قبل از شروع یک پرونده دادگاه اعلام کند که هیئت منصفه قابل قبول نیست','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('7dbd5281-f9c3-5332-a3e2-5141407d15de','caf24b84-2c0d-5080-9845-f5210aeef660',1,'all somebody’s qualities','تمام خصوصیات یک نفر','spoken & written','the particular combination of qualities that makes someone a particular type of person','[ countable usually singular ]',null,'شخصیت؛ پیکره؛ کاراکتر؛ ویژگی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He has a cheerful but quiet character.","translation":"او شخصیتی شاد اما ساکت دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071521.mp3"},{"sentence":"Children grow up with a mixture of character traits (= character qualities ) from both sides of their family.","translation":"کودکان با ترکیبی از ویژگی های شخصیتی (= ویژگی های شخصیتی) از هر دو طرف خانواده بزرگ می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667280.mp3"},{"sentence":"his temper and other character flaws (= bad qualities )","translation":"خلق و خوی و سایر عیوب شخصیت او (= خصوصیات بد)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667285.mp3"},{"sentence":"He swore, which was out of character for him.","translation":"او فحش می داد که برای او غیر اخلاقی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071525.mp3"},{"sentence":"Openness is at the heart of the American character.","translation":"باز بودن در قلب شخصیت آمریکایی قرار دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071528.mp3"}]'::jsonb,5),
('c913c70b-bc94-54b1-85ba-221a37a92823','caf24b84-2c0d-5080-9845-f5210aeef660',2,'person','شخص','spoken & written','a person in a book, play, film etc','[ countable ]',null,'یک شخص در یک کتاب، نمایشنامه، فیلم و غیره','{}'::text[],'{}'::text[],array['the main/central/leading character Alec is the central character in the play.','the lead character (= in a play, film, or television series ) DiCaprio played the lead character in Titanic.','a minor character Two of the minor characters get killed.','a television/movie/cartoon character Who’s your favourite television character?','a comic/tragic character (= a funny or sad one ) Homer Simpson is a great comic character.','fictional/fictitious (= not existing in real life ) People sometimes forget that television characters are fictional.','convincing (= seeming like a real person ) The characters were totally convincing.','a sympathetic character (= one you like ) In the book, Jeff isn’t a sympathetic character.','play a character I wanted to play the character of Danny.','portray a character (= show one in a play, book, film etc ) The main characters are brilliantly portrayed.','develop a character (= make a character become more interesting ) The movie didn’t develop his character as well as the book did.','character development (= the process of developing characters ) I thought the plot was boring and there wasn’t much character development.','a character actor (= an actor who plays interesting or unusual characters ) He’s a well-known character actor.']::text[],'[{"sentence":"Candida is the most interesting character in the play.","translation":"کاندیدا جالب ترین شخصیت نمایشنامه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667293.mp3"},{"sentence":"In the story, the main character has left his girlfriend and baby.","translation":"در داستان، شخصیت اصلی دوست دختر و نوزاد خود را ترک کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667296.mp3"},{"sentence":"Everyone recognizes Disney’s cartoon characters.","translation":"همه شخصیت های کارتونی دیزنی را می شناسند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667297.mp3"},{"sentence":"a couple of shady characters standing on the corner","translation":"چند شخصیت سایه دار در گوشه ای ایستاده اند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071576.mp3"},{"sentence":"I’m considered a reformed character these days (= someone who has stopped doing bad things ) .","translation":"این روزها من را یک شخصیت اصلاح شده می دانند (= کسی که از انجام کارهای بد دست کشیده است).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667301.mp3"},{"sentence":"Linda was something of a character.","translation":"لیندا یک شخصیت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071581.mp3"}]'::jsonb,6),
('12f50afd-e6d9-54cb-83ef-085a4745f596','caf24b84-2c0d-5080-9845-f5210aeef660',3,'qualities of something','کیفیت های چیزی','spoken & written','the particular combination of features and qualities that makes a thing or place different from all others','[ singular, uncountable ]',null,'ترکیب خاصی از ویژگی ها و کیفیت هایی که یک چیز یا مکان را از همه چیز دیگر متمایز می کند',array['nature']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The whole character of the school has changed.","translation":"کل شخصیت مدرسه تغییر کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071543.mp3"},{"sentence":"the unspoilt character of the coast","translation":"شخصیت دست نخورده ساحل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071540.mp3"},{"sentence":"The southern state became more nationalist in character.","translation":"ایالت جنوبی از نظر شخصیت ملی گرایانه تر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071546.mp3"}]'::jsonb,3),
('53ab4044-6003-57b0-8aa1-a38a0fb03162','caf24b84-2c0d-5080-9845-f5210aeef660',4,'moral strength','قدرت اخلاقی','spoken & written','a combination of qualities such as courage , loyalty , and honesty that are admired and regarded as valuable','[ uncountable ]',null,'ترکیبی از ویژگی هایی مانند شجاعت، وفاداری و صداقت که مورد تحسین قرار می گیرند و به عنوان ارزشمند تلقی می شوند.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a woman of great character","translation":"زنی با شخصیت عالی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071560.mp3"},{"sentence":"Schools were created to teach reading and mathematics, not moral character.","translation":"مدارس برای آموزش خواندن و ریاضیات ایجاد شدند، نه شخصیت اخلاقی.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667310.mp3"},{"sentence":"It takes strength of character to admit you are wrong.","translation":"اعتراف به اینکه اشتباه می کنید به قدرت شخصیت نیاز دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667311.mp3"},{"sentence":"Sport can be character building (= develop good moral qualities ) .","translation":"ورزش می تواند شخصیت سازی باشد (= ایجاد صفات اخلاقی خوب).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071564.mp3"}]'::jsonb,4),
('e29bc4cd-0ec6-51a3-b1d9-fc4b5e99b03c','caf24b84-2c0d-5080-9845-f5210aeef660',5,'interesting quality','کیفیت جالب','spoken & written','a quality that makes someone or something special and interesting','[ uncountable ]',null,'کیفیتی که کسی یا چیزی را خاص و جالب می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a red wine with a meaty character","translation":"یک شراب قرمز با شخصیت گوشتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667319.mp3"},{"sentence":"suburban houses that lack character","translation":"خانه های حومه شهر که فاقد شخصیت هستند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071553.mp3"}]'::jsonb,2),
('5de6baf4-f4bc-5df8-9786-02fcda0a1887','caf24b84-2c0d-5080-9845-f5210aeef660',6,'reputation','شهرت','formal','the opinion that people have about whether you are a good person and can be trusted','[ uncountable ]',null,'نظری که مردم در مورد اینکه آیا شما آدم خوبی هستید و می توان به او اعتماد کرد، دارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a man of previous good character","translation":"مردی با شخصیت خوب قبلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071589.mp3"},{"sentence":"The campaign was accused of character assassination (= an unfair attack on someone’s character ) because of its negative ads.","translation":"این کمپین به دلیل تبلیغات منفی خود به ترور شخصیت (= حمله ناعادلانه به شخصیت شخصی) متهم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667325.mp3"},{"sentence":"His defence called several people as character witnesses (= people who think that someone has a good character ) .","translation":"دفاعیات او چند نفر را به عنوان شاهد شخصیت (= افرادی که فکر می کنند فلانی شخصیت خوبی دارد) دعوت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667330.mp3"},{"sentence":"Mr Wetherby wrote him a character reference (= a statement about his good qualities ) .","translation":"آقای Wetherby برای او یک مرجع شخصیت نوشت (= بیانیه ای در مورد ویژگی های خوب او).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001667335.mp3"}]'::jsonb,4),
('3ad1ca5a-a561-5220-be0a-26aca617cb49','caf24b84-2c0d-5080-9845-f5210aeef660',7,'letter/sign','نامه/نشانه','spoken & written','a letter , mark , or sign used in writing, printing , or on a computer','[ countable ]',null,'یک حرف، علامت، یا علامتی که در نوشتن، چاپ یا روی رایانه استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the Chinese character for ‘horse’","translation":"حروف چینی برای \"اسب\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001071602.mp3"}]'::jsonb,1),
('0d133946-6e29-53c9-b8ee-f4df36b1fde2','61b6d10b-0114-598e-908c-acb05cd59c43',1,null,null,'spoken & written','the science that is concerned with studying the structure of substances and the way that they change or combine with each other',null,null,'شیمی، علم مواد؛ سازگاری (شیمیایی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
