('985ebb04-dec5-51a9-89bf-b96b37b5960a','d00bee0e-fd08-5c9b-9b4e-99b4f0bba476',3,null,null,'spoken & written','relating to the language , literature etc of ancient Greece and Rome',null,null,'مربوط به زبان، ادبیات و غیره یونان و روم باستان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"classical literature","translation":"ادبیات کلاسیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001789844.mp3"},{"sentence":"a classical scholar","translation":"یک محقق کلاسیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001789845.mp3"},{"sentence":"classical mythology","translation":"اساطیر کلاسیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001789846.mp3"}]'::jsonb,3),
