('b3443a45-184d-5f11-83c4-8bb7edf4135d','13f00cee-d135-57ec-9910-ac3b43b8f01f',5,'think something is important','فکر کن چیزی مهم است','spoken & written','believing that something is important','[ not before noun ]',null,'باور به اینکه چیزی مهم است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Many politicians are more concerned with power and control than with the good of the people.","translation":"بسیاری از سیاستمداران بیشتر به فکر قدرت و کنترل هستند تا خیر و صلاح مردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100358.mp3"},{"sentence":"Mr Quinn is simply concerned to hold on to his job.","translation":"آقای کوین صرفاً نگران است که کار خود را حفظ کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100361.mp3"}]'::jsonb,2),
('c616b490-f4be-5c3d-a27c-cfc1fa9de655','13f00cee-d135-57ec-9910-ac3b43b8f01f',6,'love/care','عشق / مراقبت','spoken & written','caring about someone and whether they are happy and healthy',null,null,'اهمیت دادن به کسی و اینکه آیا او شاد و سالم است یا خیر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was genuinely concerned for the children.","translation":"او واقعاً نگران بچه ها بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001100376.mp3"}]'::jsonb,1),
