('f676810a-049f-5b28-80af-ddf638f75345','256fdc53-6e16-5831-bfdb-1cdb532250ce',3,'way something develops','راهی که چیزی توسعه می یابد','spoken & written','the general way in which someone or something changes or develops','[ countable ]',null,'روش کلی که در آن شخص یا چیزی تغییر یا توسعه می یابد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We are happy with the direction the club is taking .","translation":"ما از مسیری که باشگاه در پیش گرفته خوشحالیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694965.mp3"},{"sentence":"I believe that things are heading in the right direction in South Africa.","translation":"من معتقدم که اوضاع در آفریقای جنوبی در مسیر درستی پیش می رود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001830707.mp3"},{"sentence":"The company is hoping to extend its operations in new directions.","translation":"این شرکت امیدوار است که فعالیت های خود را در جهت های جدید گسترش دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001694973.mp3"}]'::jsonb,3),
