('67bca979-544d-5edf-ae80-3961b0d66766','256fdc53-6e16-5831-bfdb-1cdb532250ce',5,'where from or where to','از کجا یا به کجا','spoken & written','where something comes from or where something leads','[ countable ]',null,'جایی که چیزی از کجا می آید یا چیزی به کجا منتهی می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The evidence all points in this direction.","translation":"شواهد همگی به این جهت اشاره دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001145594.mp3"},{"sentence":"Help came from a wholly unexpected direction.","translation":"کمک از جهتی کاملاً غیرمنتظره آمد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001145595.mp3"}]'::jsonb,2),
('1065109b-63e0-5210-9ba2-afbeb4f568c0','256fdc53-6e16-5831-bfdb-1cdb532250ce',6,'purpose','هدف','spoken & written','a general purpose or aim','[ uncountable ]',null,'یک هدف یا هدف کلی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her mother felt that Rachel’s life lacked direction .","translation":"مادرش احساس می کرد که زندگی راشل فاقد جهت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001145621.mp3"}]'::jsonb,1),
