('53b56807-4414-5f2d-8806-75349fc56b66','ee5c77b7-ea9b-5b3f-9cb3-f8b228e098a1',1,null,null,'spoken & written','a book or list of names , facts etc, usually arranged in alphabetical order',null,null,'دایرکتوری، فهرست (نام‌ها)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I couldn’t find your number in the telephone directory.","translation":"من نتوانستم شماره شما را در فهرست تلفن پیدا کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000825436.mp3"},{"sentence":"a new business directory","translation":"یک فهرست کسب و کار جدید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000825437.mp3"}]'::jsonb,2),
