('f6dadcb4-2c08-5e77-a81d-89902f06c6f6','4811c580-07ea-5cdf-af61-1cc9e4067a76',1,null,null,'spoken & written','large objects such as chairs , tables, beds, and cupboards',null,null,'اثاثیه، اثاث (خانه)؛ مبلمان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I helped him choose the furniture for his house.","translation":"من به او کمک کردم تا مبلمان خانه اش را انتخاب کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001316517.mp3"},{"sentence":"I can’t think of a single piece of furniture in my house that I bought new.","translation":"من نمی توانم حتی یک تکه مبلمان را در خانه ام که نو خریده ام فکر کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705680.mp3"},{"sentence":"office furniture","translation":"مبلمان اداری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001316518.mp3"}]'::jsonb,3),
('1a5104ab-e6d9-5629-be9a-96321866840a','89e11662-47ae-55a6-94d5-44aa0ea1363a',1,null,null,'spoken & written','considering or relating to the whole of a thing or group, rather than to details or specific cases or parts','[ sentence adverb ]',null,'عموماً، به‌طور کلی؛ معمولاً',array['broadly']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was generally a positive conversation.","translation":"به طور کلی گفتگوی مثبتی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001287229.mp3"},{"sentence":"She’s not really ill, just generally run-down.","translation":"او واقعاً بیمار نیست، فقط به طور کلی فرسوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001287230.mp3"},{"sentence":"Generally, part-timers work in low-status, low-wage occupations.","translation":"به طور کلی، کارکنان پاره وقت در مشاغل کم وضعیت و با دستمزد پایین کار می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726073.mp3"},{"sentence":"The second survey was concerned with working-class culture more generally.","translation":"نظرسنجی دوم به طور کلی تر به فرهنگ طبقه کارگر مربوط می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726074.mp3"}]'::jsonb,4),
('8b9955f8-f169-553d-a0d0-095890c04eaf','89e11662-47ae-55a6-94d5-44aa0ea1363a',2,null,null,'spoken & written','by or to most people',null,null,'توسط یا برای اکثر مردم',array['widely']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The plants are generally regarded as weeds.","translation":"گیاهان به طور کلی به عنوان علف های هرز در نظر گرفته می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001287234.mp3"},{"sentence":"a generally accepted view","translation":"یک دیدگاه عمومی پذیرفته شده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726077.mp3"},{"sentence":"It could be five years before the drug is generally available .","translation":"ممکن است پنج سال طول بکشد تا دارو به طور کلی در دسترس باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726078.mp3"}]'::jsonb,3),
