('6e8d56a1-010f-5d93-b29d-2deda0be773d','e6076431-ea5b-53b3-a97c-43dcaf507cc3',1,null,null,'spoken & written','a polite word for a man, used especially when talking to or about a man you do not know',null,null,'آقا، جناب؛ آقایان (مخاطب)؛ جنتلمن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Could you serve this gentleman please, Miss Bath?","translation":"می توانید به این آقا خدمت کنید، خانم باث؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001289021.mp3"},{"sentence":"Good morning, ladies and gentlemen .","translation":"صبح بخیر خانم ها و آقایان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718034.mp3"},{"sentence":"An elderly gentleman was asleep next to the fire.","translation":"یک آقا مسن در کنار آتش خوابیده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718038.mp3"}]'::jsonb,3),
('11e76f4a-28ad-5dc3-8316-c850cd312733','e6076431-ea5b-53b3-a97c-43dcaf507cc3',2,null,null,'spoken & written','a man who is always polite, has good manners , and treats other people well',null,null,'مردی که همیشه مودب است، اخلاق خوبی دارد و با دیگران خوب رفتار می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Martin – always the perfect gentleman – got to his feet when my mother walked in.","translation":"مارتین - همیشه یک جنتلمن عالی - وقتی مادرم وارد شد، از جایش بلند شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001289017.mp3"},{"sentence":"Mr Field was a real gentleman .","translation":"آقای فیلد یک جنتلمن واقعی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718042.mp3"}]'::jsonb,2),
('207bb74e-478a-526f-add4-6cf2b78d2304','e6076431-ea5b-53b3-a97c-43dcaf507cc3',3,null,null,'old-fashioned','a man from a high social class , especially one whose family owns a lot of property',null,null,'مردی از طبقه اجتماعی بالا، به ویژه فردی که خانواده اش دارای اموال زیادی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an English country gentleman","translation":"یک نجیب زاده انگلیسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718046.mp3"}]'::jsonb,1),
('f5d24d3a-ae48-5990-bbdb-3f6bfa2efc7c','5812da41-52aa-56b4-bb21-343f290a9f7b',1,null,null,'spoken & written','slowly, over a long period of time',null,null,'به‌تدریج، کم‌کم؛ به‌آرامی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Jill gradually became aware of an awful smell.","translation":"جیل به تدریج متوجه بوی بدی شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001331550.mp3"},{"sentence":"Gradually, my ankle got better.","translation":"کم کم مچ پایم بهتر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001710609.mp3"}]'::jsonb,2),
('000b13f3-60e5-5fca-9dd3-08e220634b0a','69ecc0dd-8de5-575c-804d-d56fcf5d9edb',1,null,null,'spoken & written','to promise to do something or to promise that something will happen',null,null,'تضمین کردن، گارانتی کردن؛ اطمینان دادن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I guarantee you’ll love this film.","translation":"من تضمین می کنم که این فیلم را دوست خواهید داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001308325.mp3"},{"sentence":"If you send the application form in straight away, I can guarantee you an interview.","translation":"اگر فوراً فرم درخواست را بفرستید، می‌توانم برایتان مصاحبه تضمین کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702394.mp3"},{"sentence":"I cannot guarantee to work for more than a year.","translation":"نمی توانم تضمین کنم که بیش از یک سال کار کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702397.mp3"},{"sentence":"The law guarantees equal rights for men and women.","translation":"قانون حقوق برابر زن و مرد را تضمین می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702398.mp3"},{"sentence":"All our products are fully guaranteed .","translation":"تمامی محصولات ما دارای ضمانت کامل می باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702400.mp3"},{"sentence":"The stereo is guaranteed against failure for a year.","translation":"استریو در برابر خرابی به مدت یک سال ضمانت دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001308338.mp3"}]'::jsonb,6),
('c207a614-a20c-57f9-a030-0b674bcd1138','69ecc0dd-8de5-575c-804d-d56fcf5d9edb',2,null,null,'spoken & written','to promise that you will pay back money that someone else has borrowed , if they do not pay it back themselves',null,null,'قول دهید که پولی را که شخص دیگری قرض گرفته است پس می دهید، اگر خودشان آن را پس ندهند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The bank will only lend me money if my parents guarantee the loan.","translation":"بانک فقط در صورتی به من پول قرض می دهد که والدینم وام را تضمین کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702407.mp3"}]'::jsonb,1),
('dbc0a37f-d9e2-52ba-8485-7aff065264b4','69ecc0dd-8de5-575c-804d-d56fcf5d9edb',3,null,null,'spoken & written','to make it certain that something will happen',null,null,'تا مطمئن شویم که اتفاقی خواهد افتاد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In movies, talent by no means guarantees success.","translation":"در فیلم ها، استعداد به هیچ وجه موفقیت را تضمین نمی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001308347.mp3"},{"sentence":"The built-in thermostat guarantees that the water remains at the same temperature all the time.","translation":"ترموستات داخلی تضمین می کند که آب همیشه در دمای یکسان باقی بماند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702411.mp3"},{"sentence":"This latest incident is guaranteed to make the situation worse.","translation":"این حادثه اخیر مطمئناً وضعیت را بدتر خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702414.mp3"},{"sentence":"Even if you complete your training, you aren’t guaranteed a job.","translation":"حتی اگر آموزش خود را کامل کنید، تضمینی برای کار ندارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702417.mp3"}]'::jsonb,4),
('64bc26ef-315c-59fa-a9d0-2ce2c32f75ea','c1d744c8-3a73-51ff-936d-d4ffb346650c',1,null,null,'spoken & written','a formal written promise to repair or replace a product if it breaks within a specific period of time',null,null,'گارانتی، تضمین کتبی؛ اطمینان',array['warranty']::text[],'{}'::text[],array['have a guarantee All our boots have a one-year guarantee for being waterproof.','come with/carry a guarantee The building work comes with a 30-year guarantee.','a one-year/two-year etc guarantee Our clocks carry a five-year guarantee.','a money-back guarantee (= one that gives you back the money you paid if there is a problem ) The company offers a 30-day, money-back guarantee on all its products.','a lifetime guarantee (= one that lasts as long as the object your have bought ) The binoculars are covered against manufacturing faults by a lifetime guarantee.','a full guarantee (= one that covers all problems ) A full guarantee comes with every purchase.']::text[],'[{"sentence":"They offer a two-year guarantee on all their electrical goods.","translation":"آنها برای تمام کالاهای برقی خود دو سال گارانتی ارائه می دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702418.mp3"},{"sentence":"Our computers come with a one-year guarantee.","translation":"کامپیوترهای ما با یک سال گارانتی عرضه می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702421.mp3"},{"sentence":"Is your TV under guarantee (= protected by a guarantee ) ?","translation":"آیا تلویزیون شما تحت ضمانت است (= با ضمانت محافظت می شود)؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001308886.mp3"},{"sentence":"a money-back guarantee","translation":"ضمانت بازگشت وجه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001781312.mp3"}]'::jsonb,4),
('0617d3e1-07b8-5854-aec8-4ccb8b40c2a3','c1d744c8-3a73-51ff-936d-d4ffb346650c',2,null,null,'spoken & written','a formal promise that something will be done',null,null,'یک وعده رسمی که کاری انجام خواهد شد','{}'::text[],'{}'::text[],array['have a guarantee All our boots have a one-year guarantee for being waterproof.','come with/carry a guarantee The building work comes with a 30-year guarantee.','a one-year/two-year etc guarantee Our clocks carry a five-year guarantee.','a money-back guarantee (= one that gives you back the money you paid if there is a problem ) The company offers a 30-day, money-back guarantee on all its products.','a lifetime guarantee (= one that lasts as long as the object your have bought ) The binoculars are covered against manufacturing faults by a lifetime guarantee.','a full guarantee (= one that covers all problems ) A full guarantee comes with every purchase.']::text[],'[{"sentence":"I’m afraid there’s no guarantee of success.","translation":"من می ترسم هیچ تضمینی برای موفقیت وجود نداشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001308892.mp3"},{"sentence":"I cannot give a guarantee that there will be no redundancies.","translation":"من نمی توانم تضمین کنم که هیچ تعدیلی وجود نخواهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001781317.mp3"}]'::jsonb,2),
