('78d8901d-f4dd-51f8-949a-9265eee99a4e','46328a93-bcd7-5663-8b8c-9f8f55036e53',1,null,null,'spoken & written','to make a problem or subject easy to notice so that people pay attention to it',null,null,'برجسته کردن، مشهود ساختن؛ نشانه‌گذاری (متن)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Your résumé should highlight your skills and achievements.","translation":"رزومه شما باید مهارت ها و دستاوردهای شما را برجسته کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020087.mp3"}]'::jsonb,1),
