('6cc5e449-e22b-51ed-aeb6-db84d66139c5','c2cf543a-5f31-5fc4-8b90-5a3c91ed6524',1,null,null,'spoken & written','a way of saying what you hope will happen, which some people think is incorrect','[ sentence adverb ]',null,'امیدوارم که؛ (پرداشتی) احتمالاً','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Hopefully, I’ll be back home by ten o‘clock.","translation":"امیدوارم تا ساعت ده به خانه برگردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360313.mp3"},{"sentence":"By then the problem will hopefully have been solved.","translation":"تا آن زمان امیدوارم مشکل حل شده باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745706.mp3"}]'::jsonb,2),
('e3f94a04-9967-53f1-b46c-4809b57cff3c','c2cf543a-5f31-5fc4-8b90-5a3c91ed6524',2,null,null,'spoken & written','in a way that shows that you are hopeful',null,null,'به گونه ای که نشان می دهد شما امیدوار هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Will there be any food left over?’ he asked hopefully.","translation":"با امیدواری پرسید: \"آیا غذا باقی می ماند؟\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360317.mp3"}]'::jsonb,1),
('7e154c59-28aa-5f82-9314-bdfd9a499edb','d0ab1ea3-d4b9-56d7-9819-3a9eb42e7dde',1,null,null,'spoken & written','all the people who live together in one house',null,null,'خانوار، خانواده ساکن یک خانه',array['house']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A growing number of households have at least one computer.","translation":"تعداد فزاینده ای از خانواده ها حداقل یک کامپیوتر دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709102.mp3"},{"sentence":"Families are classified by the occupation of the head of the household (= the person who earns the most money and is most respected in a house ) .","translation":"خانواده ها بر اساس شغل سرپرست خانوار (= شخصی که بیشترین درآمد را دارد و در یک خانه از احترام بیشتری برخوردار است) طبقه بندی می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709103.mp3"}]'::jsonb,2),
('288386cb-892e-594b-858b-b30c1d48d87f','af66e4e1-91e9-5347-8c26-0822cf25720b',1,null,null,'spoken & written','relating to looking after a house and the people in it',null,null,'مربوط به مراقبت از خانه و افراد داخل آن است',array['domestic']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"washing powder and other household products","translation":"پودر لباسشویی و سایر محصولات خانگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363164.mp3"},{"sentence":"household chores","translation":"کارهای خانه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363165.mp3"}]'::jsonb,2),
('3c17e955-5c4c-5353-9fa7-99454243384c','af66e4e1-91e9-5347-8c26-0822cf25720b',2,null,null,'spoken & written',null,null,'be a household name/word',null,'{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('36da4369-271f-5efb-9c51-9383209aa77a','a89c2f2e-af9a-51e6-8d35-5c634f285caf',1,null,null,'spoken & written','a frozen sweet food made of milk , cream , and sugar , with fruit , nuts, chocolate etc sometimes added to it','[ uncountable ]',null,'بستنی قیفی، بستنی (خامه‌ای)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"vanilla ice cream","translation":"بستنی وانیلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001541958.mp3"}]'::jsonb,1),
('368d16d7-c904-52d6-9bb0-ac9d81c1fa95','a89c2f2e-af9a-51e6-8d35-5c634f285caf',2,null,null,'spoken & written','a small amount of this food for one person','[ countable ]',null,'مقدار کمی از این غذا برای یک نفر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Mummy, can I have an ice cream?","translation":"مامان، آیا می توانم یک بستنی بخورم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001397281.mp3"}]'::jsonb,1),
('9ca6c318-3f24-52f3-b3c6-c2fa84c1844a','ebba6bb5-ea80-5cf4-a597-470bad79427c',1,null,null,'spoken & written','happening or done at once and without delay',null,null,'فوری، بی‌درنگ؛ مجاور (مجاورت)؛ نزدیک (دست)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Our immediate response to the attack was sheer horror.","translation":"واکنش فوری ما به این حمله وحشتناک بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001403373.mp3"},{"sentence":"They promise immediate action to help the unemployed.","translation":"آنها قول اقدام فوری برای کمک به بیکاران را می دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001719182.mp3"},{"sentence":"If the eyes are affected, seek immediate medical attention.","translation":"اگر چشم ها تحت تاثیر قرار گرفته اند، فورا به دنبال مراقبت های پزشکی باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001403374.mp3"}]'::jsonb,3),
('c2fa050f-8a52-56a7-9d56-005603fd7d34','ebba6bb5-ea80-5cf4-a597-470bad79427c',2,null,null,'spoken & written','existing now, and needing to be dealt with quickly','[ only before noun ]',null,'در حال حاضر موجود است و نیاز به رسیدگی سریع دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Let’s try and solve the most immediate problem .","translation":"بیایید تلاش کنیم و فوری ترین مشکل را حل کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001403380.mp3"},{"sentence":"There is an immediate danger of war.","translation":"خطر فوری جنگ وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001719189.mp3"}]'::jsonb,2),
('9b5b734f-ebfb-555d-88b5-15d8b68e2f4d','ebba6bb5-ea80-5cf4-a597-470bad79427c',3,null,null,'spoken & written','happening just before or just after someone or something else','[ only before noun ]',null,'درست قبل یا بعد از شخص یا چیز دیگری اتفاق می افتد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The most immediate effect of retirement is a dramatic reduction in living standards.","translation":"فوری ترین اثر بازنشستگی کاهش چشمگیر استانداردهای زندگی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001719193.mp3"},{"sentence":"He promised that there would be no tax increases in the immediate future .","translation":"او وعده داد که در آینده نزدیک هیچ افزایش مالیاتی وجود نخواهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001719197.mp3"}]'::jsonb,2),
('209b43f2-5506-5ddc-ae92-3e4e3b8ff034','ebba6bb5-ea80-5cf4-a597-470bad79427c',4,null,null,'spoken & written','next to, or very near to, a particular place','[ only before noun ]',null,'در کنار یا بسیار نزدیک به یک مکان خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It is a thriving shopping centre for the people who live in the immediate area .","translation":"این یک مرکز خرید پر رونق برای افرادی است که در منطقه نزدیک زندگی می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001403395.mp3"}]'::jsonb,1),
('7fd92091-24a5-5887-9e43-3b028ce051fc','ebba6bb5-ea80-5cf4-a597-470bad79427c',5,null,null,'spoken & written',null,null,'immediate family','فوری، بی‌درنگ؛ مجاور (مجاورت)؛ نزدیک (دست)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('57b23303-d4b8-585c-a82e-f9b537cf0c19','d3ed50d1-dabd-5190-a2f4-08ce494621d4',1,null,null,'spoken & written','to take action or make changes that you have officially decided should happen',null,null,'اجرا کردن، به‌کار بستن (تصمیم)؛ ابزار (وسایل)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We have decided to implement the committee’s recommendations in full .","translation":"ما تصمیم گرفته ایم که توصیه های کمیته را به طور کامل اجرا کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001405068.mp3"}]'::jsonb,1),
('e80b0265-ad39-5075-adc9-076df95f7723','03b040fc-a77d-5fb0-b725-9bebb9735833',1,null,null,'spoken & written','a tool , especially one used for outdoor physical work',null,null,'یک ابزار، به ویژه ابزاری که برای کارهای فیزیکی در فضای باز استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0a604bb0-b6ba-5219-93ec-dc3bc57793a3','c9d75c87-9ee3-5cb2-bc0d-275c85d30c06',1,null,null,'spoken & written','an important event , decision , problem etc has a big effect or influence on people’s lives or on events in the future',null,null,'مهم، عمده؛ اهمیت‌دار (شخص)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a very important meeting","translation":"یک جلسه بسیار مهم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001406998.mp3"},{"sentence":"The accident taught him an important lesson.","translation":"این حادثه درس مهمی به او داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709494.mp3"},{"sentence":"Happiness is more important than money.","translation":"خوشبختی مهمتر از پول است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709495.mp3"},{"sentence":"‘What did you say?’ ‘Oh, nothing important.’","translation":"«چی گفتی؟» «اوه، چیز مهمی نیست.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709496.mp3"},{"sentence":"It’s important to explain the procedure to the patient.","translation":"توضیح این روش برای بیمار مهم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001834373.mp3"},{"sentence":"It’s vitally important that you understand the danger.","translation":"بسیار مهم است که خطر را درک کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001407005.mp3"},{"sentence":"It was important for the president to continue his schedule, regardless of the bomb threat.","translation":"برای رئیس جمهور مهم بود که برنامه خود را بدون توجه به تهدید بمب گذاری ادامه دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709505.mp3"},{"sentence":"Nothing could be more important to me than my family.","translation":"هیچ چیز نمی تواند برای من مهمتر از خانواده ام باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709508.mp3"}]'::jsonb,8),
('16166951-305e-509a-a63c-83ee7c4d3f1c','c9d75c87-9ee3-5cb2-bc0d-275c85d30c06',2,null,null,'spoken & written','people who are important have a lot of power or influence',null,null,'افرادی که مهم هستند قدرت یا نفوذ زیادی دارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a very important customer","translation":"یک مشتری بسیار مهم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001407012.mp3"},{"sentence":"They carry guns because it makes them feel important .","translation":"آنها اسلحه حمل می کنند زیرا به آنها احساس مهم بودن می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709509.mp3"}]'::jsonb,2),
('186ca22d-02cc-5f9a-97f8-4ce041b9504b','9daeef9e-3e80-5eef-af1a-55adc4d4a04c',1,null,null,'spoken & written','used to introduce something or someone that is part of a larger group or amount you have just mentioned',null,null,'به‌علاوه، شاملِ (بخشی از کل)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The price is £25.50, including postage and packing.","translation":"قیمت 25.50 پوند شامل هزینه پست و بسته بندی می باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001372238.mp3"},{"sentence":"You’ll need a variety of skills, including leadership and negotiating.","translation":"شما به مهارت های مختلفی از جمله رهبری و مذاکره نیاز دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001372237.mp3"},{"sentence":"The cost is $49.95 excluding tax.","translation":"هزینه 49.95 دلار بدون احتساب مالیات است.","audio_url":null}]'::jsonb,3),
('a71f58da-502d-5119-862b-6adb0ff9f86a','b1b2386b-1812-5df1-9905-9018b0bfb796',1,null,null,'spoken & written','a disease that affects a particular part of your body and is caused by bacteria or a virus','[ countable ]',null,'عفونت، عفونت؛ آلودگی','{}'::text[],'{}'::text[],array['have an infection I think you’ve got an infection, so you need to rest.','suffer from an infection He was suffering from an infection of the lungs.','get/develop an infection She got a nasty throat infection which meant she couldn’t sing.','treat an infection Antibiotics are used to treat the infection.','fight/combat an infection A new drug is being developed to combat the infection.','spread an infection ( also transmit an infection formal ) Pregnant women can transmit the infection to their unborn child.','an infection spreads The infection spread to her chest.','an infection clears up (= goes away ) Although the infection cleared up, he still felt weak.','be exposed to an infection He was exposed to the infection while he was travelling in India.','serious/severe He was admitted to hospital with a serious infection.','slight/minor (= not serious ) She’s suffering from a slight infection.','nasty informal (= a serious infection ) He’s got a really nasty infection.','acute medical (= a serious infection that develops suddenly ) The disease usually occurs as an acute infection of the throat.','an ear/eye infection She was given antibiotics for an ear infection.','a chest infection (= an infection in the lungs ) I’ve got a bad cough, but the doctor says it isn’t a chest infection.','a throat/kidney etc infection He developed a severe throat infection.','a bacterial/viral/fungal infection (= caused by bacteria, a virus, or a fungus ) Antibiotics are not effective against viral infections.','a secondary infection medical (= an additional infection that happens as a result of the main illness ) Often, scratching the skin because it is itchy results in secondary infection.','the source of an infection Doctors are trying to locate the source of the infection.']::text[],'[{"sentence":"The baby had an ear infection.","translation":"نوزاد عفونت گوش داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000840.mp3"},{"sentence":"an infection of the bladder","translation":"عفونت مثانه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000841.mp3"}]'::jsonb,2),
('44385e0d-3b20-564d-bc81-5a612e44732a','b1b2386b-1812-5df1-9905-9018b0bfb796',2,null,null,'spoken & written','when someone is infected by a disease','[ uncountable ]',null,'وقتی فردی به بیماری مبتلا می شود','{}'::text[],'{}'::text[],array['have an infection I think you’ve got an infection, so you need to rest.','suffer from an infection He was suffering from an infection of the lungs.','get/develop an infection She got a nasty throat infection which meant she couldn’t sing.','treat an infection Antibiotics are used to treat the infection.','fight/combat an infection A new drug is being developed to combat the infection.','spread an infection ( also transmit an infection formal ) Pregnant women can transmit the infection to their unborn child.','an infection spreads The infection spread to her chest.','an infection clears up (= goes away ) Although the infection cleared up, he still felt weak.','be exposed to an infection He was exposed to the infection while he was travelling in India.','serious/severe He was admitted to hospital with a serious infection.','slight/minor (= not serious ) She’s suffering from a slight infection.','nasty informal (= a serious infection ) He’s got a really nasty infection.','acute medical (= a serious infection that develops suddenly ) The disease usually occurs as an acute infection of the throat.','an ear/eye infection She was given antibiotics for an ear infection.','a chest infection (= an infection in the lungs ) I’ve got a bad cough, but the doctor says it isn’t a chest infection.','a throat/kidney etc infection He developed a severe throat infection.','a bacterial/viral/fungal infection (= caused by bacteria, a virus, or a fungus ) Antibiotics are not effective against viral infections.','a secondary infection medical (= an additional infection that happens as a result of the main illness ) Often, scratching the skin because it is itchy results in secondary infection.','the source of an infection Doctors are trying to locate the source of the infection.']::text[],'[{"sentence":"Always sterilize the needle to prevent infection.","translation":"برای جلوگیری از عفونت، همیشه سوزن را استریل کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001450515.mp3"}]'::jsonb,1),
('0f449309-ef4a-5bf1-b833-38588c40a868','b7471112-9ee0-583f-8d51-3424209a298c',1,null,null,'spoken & written','a continuing increase in prices , or the rate at which prices increase',null,null,'تورم، گرانی؛ (هوا) پف (قنات)','{}'::text[],'{}'::text[],array['low France had achieved low inflation and steady growth.','high Inflation remained high throughout this period.','annual inflation Annual inflation in 1990 was 8.1%.','rising inflation The country was hit by rising inflation.','spiralling/soaring inflation (= inflation that is increasing quickly and out of control ) Argentina was suffering from spiralling inflation.','price/wage inflation (= increasing prices/wages ) Price inflation was running at about twelve percent last summer.','the inflation rate/the rate of inflation The current inflation rate stands at 4.1%.','the inflation figures April''s inflation figures are likely to show a further fall.','cause/lead to inflation Too much government borrowing can lead to inflation.','fuel inflation/push up inflation (= make inflation worse ) The increase in food prices is fuelling inflation. There are now fears that price rises will push up inflation.','control/curb inflation (= prevent it from increasing more ) These measures are designed to curb inflation.','fight/combat inflation An economic plan to combat inflation was drawn up.','reduce inflation/get inflation down The government has promised to reduce inflation to 3%. The government''s top priority is to get inflation down to 2%.','keep inflation down (= keep it at a low level ) These policies will help to keep inflation down.','inflation rises Inflation rose steadily from the mid-1960s.','inflation falls Inflation fell by 0.5% last month.','inflation is running at 3%/4% etc ( also inflation stands at 3%/4% etc ) (= used to talk about the present rate of inflation ) Inflation currently stands at 3.2%.','keep pace with inflation (= be at the same level as inflation ) Salaries have not kept pace with inflation.']::text[],'[{"sentence":"Inflation is now at over 16%.","translation":"تورم اکنون بالای 16 درصد است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000843.mp3"}]'::jsonb,1),
('6d9f4860-8a78-5454-987a-53712e499ea9','b7471112-9ee0-583f-8d51-3424209a298c',2,null,null,'spoken & written','the process of filling something with air',null,null,'فرآیند پر کردن چیزی با هوا','{}'::text[],'{}'::text[],array['low France had achieved low inflation and steady growth.','high Inflation remained high throughout this period.','annual inflation Annual inflation in 1990 was 8.1%.','rising inflation The country was hit by rising inflation.','spiralling/soaring inflation (= inflation that is increasing quickly and out of control ) Argentina was suffering from spiralling inflation.','price/wage inflation (= increasing prices/wages ) Price inflation was running at about twelve percent last summer.','the inflation rate/the rate of inflation The current inflation rate stands at 4.1%.','the inflation figures April''s inflation figures are likely to show a further fall.','cause/lead to inflation Too much government borrowing can lead to inflation.','fuel inflation/push up inflation (= make inflation worse ) The increase in food prices is fuelling inflation. There are now fears that price rises will push up inflation.','control/curb inflation (= prevent it from increasing more ) These measures are designed to curb inflation.','fight/combat inflation An economic plan to combat inflation was drawn up.','reduce inflation/get inflation down The government has promised to reduce inflation to 3%. The government''s top priority is to get inflation down to 2%.','keep inflation down (= keep it at a low level ) These policies will help to keep inflation down.','inflation rises Inflation rose steadily from the mid-1960s.','inflation falls Inflation fell by 0.5% last month.','inflation is running at 3%/4% etc ( also inflation stands at 3%/4% etc ) (= used to talk about the present rate of inflation ) Inflation currently stands at 3.2%.','keep pace with inflation (= be at the same level as inflation ) Salaries have not kept pace with inflation.']::text[],'[]'::jsonb,0),
('8aceec0d-4e64-5cae-a524-89e533e892e3','154f3bcf-93a6-5459-b29b-5a4d720c8278',1,null,null,'spoken & written','the power to affect the way someone or something develops , behaves , or thinks, without using direct force or orders','[ countable, uncountable ]',null,'نفوذ، تأثیر؛ مرجع (نفوذ)','{}'::text[],'{}'::text[],array['have an influence on somebody/something His works have had an influence on many modern writers.','exert an influence formal (= have an influence ) Technology exerts a powerful influence over our lives.','use your influence She wasn’t afraid to use her influence to get what she wanted.','exercise/wield influence formal (= use it ) The Federal Reserve exercises influence on the economy by setting short-term interest rates.','come/fall under the influence of somebody/something (= be influenced by someone or something ) They had come under the influence of a religious sect.','extend your influence (= make your influence larger ) Syria had the opportunity to extend its influence in the region.','a good/positive influence Television can have a positive influence on young people.','a bad/negative influence He thought her friends were a bad influence.','a big/great influence The goalkeeper’s injury had a big influence on the match.','an important/significant/major influence Parents have an important influence on children''s development. He was a major influence on my musical tastes.','considerable influence Well-organized pressure groups can exert considerable influence on the government.','a strong/powerful influence The press can have a powerful influence on the way people vote.','a deep/profound influence His writings had a profound influence on the Romantic poets.','a growing influence Many people are worried about the growing influence of these websites.','a lasting influence (= continuing for a long time ) His travels in Africa had a lasting influence on his work.','a direct/indirect influence The Cubist painters had a direct influence on his work. The federal government has an indirect influence on investment through its control of bank credits.','a calming/soothing influence The music seemed to have a calming influence.','somebody’s personal influence Frank used his personal influence to get his son a job at the newspaper.','political/cultural/economic influence French political influence began to dominate the country.','outside/external influence (= happening from outside a country or a situation ) They must make their own decisions, free from external influence. The US remains the biggest outside influence on the country.','undue influence (= too much influence ) He felt that the United States wielded undue influence in Europe.']::text[],'[{"sentence":"As a scientist, his influence was immense.","translation":"به عنوان یک دانشمند، تأثیر او بسیار زیاد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000844.mp3"},{"sentence":"the unions’ influence over local politics","translation":"نفوذ اتحادیه ها بر سیاست های محلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745110.mp3"}]'::jsonb,2),
('15b2eb02-1c94-595c-a1cb-64161e142dcf','154f3bcf-93a6-5459-b29b-5a4d720c8278',2,null,null,'spoken & written','someone or something that has an influence on other people or things','[ countable ]',null,'کسی یا چیزی که بر افراد یا چیزهای دیگر تأثیر می گذارد','{}'::text[],'{}'::text[],array['have an influence on somebody/something His works have had an influence on many modern writers.','exert an influence formal (= have an influence ) Technology exerts a powerful influence over our lives.','use your influence She wasn’t afraid to use her influence to get what she wanted.','exercise/wield influence formal (= use it ) The Federal Reserve exercises influence on the economy by setting short-term interest rates.','come/fall under the influence of somebody/something (= be influenced by someone or something ) They had come under the influence of a religious sect.','extend your influence (= make your influence larger ) Syria had the opportunity to extend its influence in the region.','a good/positive influence Television can have a positive influence on young people.','a bad/negative influence He thought her friends were a bad influence.','a big/great influence The goalkeeper’s injury had a big influence on the match.','an important/significant/major influence Parents have an important influence on children''s development. He was a major influence on my musical tastes.','considerable influence Well-organized pressure groups can exert considerable influence on the government.','a strong/powerful influence The press can have a powerful influence on the way people vote.','a deep/profound influence His writings had a profound influence on the Romantic poets.','a growing influence Many people are worried about the growing influence of these websites.','a lasting influence (= continuing for a long time ) His travels in Africa had a lasting influence on his work.','a direct/indirect influence The Cubist painters had a direct influence on his work. The federal government has an indirect influence on investment through its control of bank credits.','a calming/soothing influence The music seemed to have a calming influence.','somebody’s personal influence Frank used his personal influence to get his son a job at the newspaper.','political/cultural/economic influence French political influence began to dominate the country.','outside/external influence (= happening from outside a country or a situation ) They must make their own decisions, free from external influence. The US remains the biggest outside influence on the country.','undue influence (= too much influence ) He felt that the United States wielded undue influence in Europe.']::text[],'[{"sentence":"Gayle’s mother said I was a bad influence on her daughter.","translation":"مادر گیل گفت که من تأثیر بدی روی دخترش داشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001451366.mp3"},{"sentence":"For centuries the country remained untouched by outside influences .","translation":"برای قرن ها این کشور از تأثیرات خارجی دست نخورده باقی ماند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745118.mp3"}]'::jsonb,2),
('11e9af0e-ca68-5ace-a466-d8d09169482f','154f3bcf-93a6-5459-b29b-5a4d720c8278',3,null,null,'spoken & written',null,null,'under the influence (of alcohol/drink/drugs etc)','نفوذ، تأثیر؛ مرجع (نفوذ)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('1d045b23-a52a-583f-ac3c-6afde991e1f3','8c89eb8f-c8fd-5b58-a21e-ed8fdb9e510d',1,null,null,'spoken & written','to affect the way someone or something develops, behaves, thinks etc without directly forcing or ordering them',null,null,'تأثیر گذاشتن بر؛ نفوذ کردن (در)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Marx was strongly influenced by the historian Niebuhr.","translation":"مارکس به شدت تحت تأثیر نیبور مورخ بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745122.mp3"},{"sentence":"Several factors are likely to influence this decision.","translation":"عوامل متعددی احتمالاً بر این تصمیم تأثیر می گذارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001451388.mp3"},{"sentence":"What influenced you to take up nursing?","translation":"چه چیزی شما را تحت تأثیر قرار داد تا به پرستاری روی بیاورید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745128.mp3"}]'::jsonb,3),
('15e5630c-426d-5851-b9f0-f45b11bd3cac','f35eadc1-9d76-56ee-8dcb-94778d433745',1,null,null,'spoken & written','at the beginning',null,null,'در ابتدا، در آغاز؛ نخست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Stan initially wanted to go to medical school.","translation":"استن در ابتدا می خواست به دانشکده پزشکی برود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001412980.mp3"},{"sentence":"Initially, I thought I would only stay there a year.","translation":"در ابتدا فکر می کردم فقط یک سال آنجا می مانم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750753.mp3"}]'::jsonb,2),
('056e1882-1a53-56e6-993c-d2fb34df6aa0','4cebcef0-ce9d-549d-b295-d59dd417d814',1,null,null,'spoken & written','an official whose job is to check that something is satisfactory and that rules are being obeyed',null,null,'بازرس، معاینه‌گر؛ پاسبان (پلیس)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"ticket inspectors","translation":"بازرسان بلیط","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001415971.mp3"},{"sentence":"a Health and Safety inspector","translation":"یک بازرس ایمنی و بهداشت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001415972.mp3"},{"sentence":"Standards of discipline at the school were strongly criticized in the inspector’s report.","translation":"استانداردهای انضباط در مدرسه در گزارش بازرس به شدت مورد انتقاد قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718939.mp3"}]'::jsonb,3),
('985cc993-5406-5e12-bc9a-e9c119cac6ba','4cebcef0-ce9d-549d-b295-d59dd417d814',2,null,null,'spoken & written','a police officer of middle rank',null,'chief inspector','یک افسر پلیس درجه متوسط','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Inspector Blake","translation":"بازرس بلیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001415976.mp3"}]'::jsonb,1),
('6e1fd255-a1f6-5913-875f-36232e997ffb','674e74bf-94fd-5c0d-80c8-f8c300bf0eb9',1,null,null,'spoken & written','an organization that has a particular purpose such as scientific or educational work, or the building where this organization is based',null,null,'مؤسسه، نهاد (پژوهشی)؛ تأسیس کردن (رسمی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"research institutes","translation":"موسسات تحقیقاتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417174.mp3"},{"sentence":"the Institute for Space Studies","translation":"موسسه مطالعات فضایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417173.mp3"}]'::jsonb,2),
('4fac342b-7be0-58dd-9322-7d8be8e345b0','21867b60-68a5-5d51-96d0-7c65c656c512',1,null,null,'spoken & written','to introduce or start a system, rule , legal process etc',null,null,'برای معرفی یا شروع یک سیستم، قانون، فرآیند قانونی و غیره',array['begin']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We had no choice but to institute court proceedings against the airline.","translation":"ما چاره ای نداشتیم جز این که علیه شرکت هواپیمایی اقدام کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417185.mp3"}]'::jsonb,1),
('b67de4bd-e43d-5e20-b271-751befc47cc6','3f8c47f3-de48-55f7-a6d2-b2292648e399',1,null,null,'spoken & written','an arrangement with a company in which you pay them money, especially regularly, and they pay the costs if something bad happens, for example if you become ill or your car is damaged','[ uncountable ]','life insurance','بیمه، بیمه‌نامه؛ حق بیمه','{}'::text[],'{}'::text[],array['health/medical insurance None of her family have private health insurance.','travel insurance Most banks are also able to arrange travel insurance.','car/motor insurance He was fined for driving without motor insurance.','house/home insurance The damage may be covered by your house insurance.','life insurance Surprisingly few families have adequate life insurance.','accident insurance You also get free travel accident insurance if you pay for your tickets with a credit card.','comprehensive insurance (= car insurance that pays for damage whether it is caused by you or by someone else ) The cost of comprehensive insurance is likely to drop.','third-party insurance (= insurance that pays money to someone who is hurt or whose property is damaged by something you have done ) You are legally obliged to take out third-party insurance.','an insurance policy (= an insurance agreement ) This insurance policy represents excellent value for money.','an insurance claim She filed an insurance claim for the missing jewellery.','an insurance company Rachel works for an insurance company.','an insurance broker (= a company or person that arranges and sells insurance to people ) Bellingham practised as an insurance broker.','an insurance scheme The costs involved in private medical insurance schemes have risen steeply.','an insurance premium (= money that you pay regularly to an insurance company ) Your insurance premium is payable when you make your holiday booking.','an insurance payment He''d fallen behind with his insurance payments.','an insurance certificate/a certificate of insurance The courts recognize the insurance certificate as evidence of being insured.','insurance cover The scheme provides full insurance cover for pre-existing medical conditions.','insurance fraud Insurance fraud costs the industry millions of pounds each year.','an insurance salesman He offered me a post as a life insurance salesman.','the insurance industry The insurance industry is very competitive.','have insurance (= have an insurance policy ) Do you have insurance on your yacht?','be covered by insurance (= be included in an insurance policy ) Flood damage isn''t covered by the insurance.','take out insurance (= buy an insurance policy ) We decided to take out insurance on the house and its contents.','get insurance informal: I''m thinking of getting house insurance.','buy insurance You can buy insurance against risks of all kinds.','claim something on your insurance (= get an insurance company to pay for something ) He claimed the money back on his travel insurance.','arrange insurance A finance company will be able to arrange insurance for you.','sell insurance The company sells insurance alongside its electrical products.','insurance covers something The insurance covered the cost of rebuilding the house after the fire.','insurance pays for something His insurance paid for the damage to the car.']::text[],'[{"sentence":"Your father took out insurance to cover the mortgage.","translation":"پدرت برای تامین وام مسکن بیمه گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001798197.mp3"},{"sentence":"insurance against loss of income due to unemployment","translation":"بیمه از دست دادن درآمد ناشی از بیکاری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417845.mp3"},{"sentence":"Do you have insurance on your house and its contents?","translation":"آیا خانه و محتویات آن بیمه دارید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417848.mp3"},{"sentence":"We can probably claim the damage on our insurance.","translation":"احتمالاً می توانیم خسارت بیمه خود را مطالبه کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417852.mp3"}]'::jsonb,4),
('23776f26-a7c7-57da-b899-0b0aad2f0192','3f8c47f3-de48-55f7-a6d2-b2292648e399',2,null,null,'spoken & written','the business of providing insurance','[ uncountable ]',null,'کسب و کار ارائه بیمه','{}'::text[],'{}'::text[],array['health/medical insurance None of her family have private health insurance.','travel insurance Most banks are also able to arrange travel insurance.','car/motor insurance He was fined for driving without motor insurance.','house/home insurance The damage may be covered by your house insurance.','life insurance Surprisingly few families have adequate life insurance.','accident insurance You also get free travel accident insurance if you pay for your tickets with a credit card.','comprehensive insurance (= car insurance that pays for damage whether it is caused by you or by someone else ) The cost of comprehensive insurance is likely to drop.','third-party insurance (= insurance that pays money to someone who is hurt or whose property is damaged by something you have done ) You are legally obliged to take out third-party insurance.','an insurance policy (= an insurance agreement ) This insurance policy represents excellent value for money.','an insurance claim She filed an insurance claim for the missing jewellery.','an insurance company Rachel works for an insurance company.','an insurance broker (= a company or person that arranges and sells insurance to people ) Bellingham practised as an insurance broker.','an insurance scheme The costs involved in private medical insurance schemes have risen steeply.','an insurance premium (= money that you pay regularly to an insurance company ) Your insurance premium is payable when you make your holiday booking.','an insurance payment He''d fallen behind with his insurance payments.','an insurance certificate/a certificate of insurance The courts recognize the insurance certificate as evidence of being insured.','insurance cover The scheme provides full insurance cover for pre-existing medical conditions.','insurance fraud Insurance fraud costs the industry millions of pounds each year.','an insurance salesman He offered me a post as a life insurance salesman.','the insurance industry The insurance industry is very competitive.','have insurance (= have an insurance policy ) Do you have insurance on your yacht?','be covered by insurance (= be included in an insurance policy ) Flood damage isn''t covered by the insurance.','take out insurance (= buy an insurance policy ) We decided to take out insurance on the house and its contents.','get insurance informal: I''m thinking of getting house insurance.','buy insurance You can buy insurance against risks of all kinds.','claim something on your insurance (= get an insurance company to pay for something ) He claimed the money back on his travel insurance.','arrange insurance A finance company will be able to arrange insurance for you.','sell insurance The company sells insurance alongside its electrical products.','insurance covers something The insurance covered the cost of rebuilding the house after the fire.','insurance pays for something His insurance paid for the damage to the car.']::text[],'[{"sentence":"My brother works in insurance.","translation":"برادر من در بیمه کار می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417870.mp3"},{"sentence":"the insurance industry","translation":"صنعت بیمه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001798209.mp3"}]'::jsonb,2),
('e273747b-52f0-55af-ba83-7465a1f71c80','3f8c47f3-de48-55f7-a6d2-b2292648e399',3,null,null,'spoken & written','the money that you pay regularly to an insurance company','[ uncountable ]',null,'پولی که به طور منظم به یک شرکت بیمه می پردازید',array['insurance premium']::text[],'{}'::text[],array['health/medical insurance None of her family have private health insurance.','travel insurance Most banks are also able to arrange travel insurance.','car/motor insurance He was fined for driving without motor insurance.','house/home insurance The damage may be covered by your house insurance.','life insurance Surprisingly few families have adequate life insurance.','accident insurance You also get free travel accident insurance if you pay for your tickets with a credit card.','comprehensive insurance (= car insurance that pays for damage whether it is caused by you or by someone else ) The cost of comprehensive insurance is likely to drop.','third-party insurance (= insurance that pays money to someone who is hurt or whose property is damaged by something you have done ) You are legally obliged to take out third-party insurance.','an insurance policy (= an insurance agreement ) This insurance policy represents excellent value for money.','an insurance claim She filed an insurance claim for the missing jewellery.','an insurance company Rachel works for an insurance company.','an insurance broker (= a company or person that arranges and sells insurance to people ) Bellingham practised as an insurance broker.','an insurance scheme The costs involved in private medical insurance schemes have risen steeply.','an insurance premium (= money that you pay regularly to an insurance company ) Your insurance premium is payable when you make your holiday booking.','an insurance payment He''d fallen behind with his insurance payments.','an insurance certificate/a certificate of insurance The courts recognize the insurance certificate as evidence of being insured.','insurance cover The scheme provides full insurance cover for pre-existing medical conditions.','insurance fraud Insurance fraud costs the industry millions of pounds each year.','an insurance salesman He offered me a post as a life insurance salesman.','the insurance industry The insurance industry is very competitive.','have insurance (= have an insurance policy ) Do you have insurance on your yacht?','be covered by insurance (= be included in an insurance policy ) Flood damage isn''t covered by the insurance.','take out insurance (= buy an insurance policy ) We decided to take out insurance on the house and its contents.','get insurance informal: I''m thinking of getting house insurance.','buy insurance You can buy insurance against risks of all kinds.','claim something on your insurance (= get an insurance company to pay for something ) He claimed the money back on his travel insurance.','arrange insurance A finance company will be able to arrange insurance for you.','sell insurance The company sells insurance alongside its electrical products.','insurance covers something The insurance covered the cost of rebuilding the house after the fire.','insurance pays for something His insurance paid for the damage to the car.']::text[],'[{"sentence":"How much is the insurance on your car?","translation":"بیمه ماشین شما چقدر است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417865.mp3"}]'::jsonb,1),
('99f69417-df98-5ef6-b66b-4c854e2c3665','3f8c47f3-de48-55f7-a6d2-b2292648e399',4,null,null,'spoken & written','protection against something bad happening','[ singular, uncountable ]',null,'محافظت در برابر اتفاق بد','{}'::text[],'{}'::text[],array['health/medical insurance None of her family have private health insurance.','travel insurance Most banks are also able to arrange travel insurance.','car/motor insurance He was fined for driving without motor insurance.','house/home insurance The damage may be covered by your house insurance.','life insurance Surprisingly few families have adequate life insurance.','accident insurance You also get free travel accident insurance if you pay for your tickets with a credit card.','comprehensive insurance (= car insurance that pays for damage whether it is caused by you or by someone else ) The cost of comprehensive insurance is likely to drop.','third-party insurance (= insurance that pays money to someone who is hurt or whose property is damaged by something you have done ) You are legally obliged to take out third-party insurance.','an insurance policy (= an insurance agreement ) This insurance policy represents excellent value for money.','an insurance claim She filed an insurance claim for the missing jewellery.','an insurance company Rachel works for an insurance company.','an insurance broker (= a company or person that arranges and sells insurance to people ) Bellingham practised as an insurance broker.','an insurance scheme The costs involved in private medical insurance schemes have risen steeply.','an insurance premium (= money that you pay regularly to an insurance company ) Your insurance premium is payable when you make your holiday booking.','an insurance payment He''d fallen behind with his insurance payments.','an insurance certificate/a certificate of insurance The courts recognize the insurance certificate as evidence of being insured.','insurance cover The scheme provides full insurance cover for pre-existing medical conditions.','insurance fraud Insurance fraud costs the industry millions of pounds each year.','an insurance salesman He offered me a post as a life insurance salesman.','the insurance industry The insurance industry is very competitive.','have insurance (= have an insurance policy ) Do you have insurance on your yacht?','be covered by insurance (= be included in an insurance policy ) Flood damage isn''t covered by the insurance.','take out insurance (= buy an insurance policy ) We decided to take out insurance on the house and its contents.','get insurance informal: I''m thinking of getting house insurance.','buy insurance You can buy insurance against risks of all kinds.','claim something on your insurance (= get an insurance company to pay for something ) He claimed the money back on his travel insurance.','arrange insurance A finance company will be able to arrange insurance for you.','sell insurance The company sells insurance alongside its electrical products.','insurance covers something The insurance covered the cost of rebuilding the house after the fire.','insurance pays for something His insurance paid for the damage to the car.']::text[],'[{"sentence":"An extra lock on the door is an added insurance against burglars.","translation":"قفل اضافی روی درب بیمه ای اضافه در برابر سارقان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417877.mp3"}]'::jsonb,1),
('7f20ab14-e175-5046-841c-4b7986c849c9','0d98b353-a8bd-515c-8ccc-c769b1f8fba9',1,null,null,'spoken & written','a plan or desire to do something',null,null,'قصد، نیت؛ منظور','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I have no intention of retiring just yet.","translation":"من هنوز قصد بازنشستگی ندارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001419359.mp3"},{"sentence":"They went into town with the intention of visiting the library.","translation":"آنها به قصد بازدید از کتابخانه به شهر رفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001419362.mp3"},{"sentence":"It is our intention to be the number one distributor of health products.","translation":"هدف ما این است که توزیع کننده شماره یک محصولات بهداشتی باشیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001419365.mp3"},{"sentence":"He thinks the minister is full of good intentions that won’t be carried out.","translation":"او فکر می کند که وزیر پر از نیات خیر است که انجام نمی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020112.mp3"}]'::jsonb,4),
('f2a41923-ba74-5ae6-8094-a3d1590d3242','4a18df22-624b-5c59-8c52-e070565a0e3a',1,null,null,'spoken & written','to translate spoken words from one language into another','[ intransitive, transitive ]',null,'ترجمه شفاهی (همراه با)؛ تفسیر کردن (متن)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They spoke good Spanish, and promised to interpret for me.","translation":"آنها به خوبی اسپانیایی صحبت می کردند و قول دادند که برای من ترجمه کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001421091.mp3"}]'::jsonb,1),
('0edad705-59ae-55c3-9c33-e71686310840','4a18df22-624b-5c59-8c52-e070565a0e3a',2,null,null,'spoken & written','to believe that something someone does or something that happens has a particular meaning','[ transitive ]',null,'باور به اینکه کاری که کسی انجام می دهد یا چیزی که اتفاق می افتد معنای خاصی دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His refusal to work late was interpreted as a lack of commitment to the company.","translation":"امتناع او از کار تا دیروقت به عنوان عدم تعهد به شرکت تعبیر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001421103.mp3"}]'::jsonb,1),
('f732c860-ce12-5114-b002-82468729e0b5','4a18df22-624b-5c59-8c52-e070565a0e3a',3,null,null,'spoken & written','to explain the meaning of something','[ transitive ]',null,'برای توضیح معنای چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Freud’s attempts to interpret the meaning of dreams","translation":"تلاش فروید برای تفسیر معنای رویاها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001421108.mp3"}]'::jsonb,1),
('042e0772-b612-5573-b884-64e3d8337365','4a18df22-624b-5c59-8c52-e070565a0e3a',4,null,null,'spoken & written','to perform a part in a play, a piece of music etc in a way that shows your feelings about it or what you think it means','[ transitive ]',null,'اجرای بخشی در یک نمایشنامه، یک قطعه موسیقی و غیره به گونه ای که احساسات شما را در مورد آن یا آنچه فکر می کنید به معنای آن است را نشان دهد.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('8a274655-f6b4-50ac-b116-e635831af544','6b28a5a7-c0ad-5925-a138-db221c77ef30',1,null,null,'spoken & written','a formal meeting at which someone is asked questions in order to find out whether they are suitable for a job, course of study etc','[ countable, uncountable ]',null,'مصاحبه، گفت‌وگوی رسمی؛ مصاحبه (استخدام)','{}'::text[],'{}'::text[],array['have an interview She has an interview next week for a teaching job in Paris.','go for an interview ( also attend an interview formal ) I went for an interview at a software company yesterday.','get an interview He was one of only five people to get an interview out of more than 100 people who applied.','be called/invited for (an) interview Applicants who are called for interview may be asked to have a medical exam.','do an interview ( also conduct an interview formal ) The interview was conducted in French.','give somebody an interview (= interview someone ) We gave her an interview, but decided not to offer her the job.','a job interview Try to predict the questions you might get in your job interview.','an informal/formal interview Applicants will normally have an informal interview with the manager. One out of every six candidates reached the formal interview.','the first interview ( also the preliminary interview formal ) He felt the first interview had gone well.','a second/follow-up interview (= a more detailed interview after you have been successful in a previous interview ) She was asked back for a second interview.','a mock interview (= one that you do for practice, rather than a real interview ) Mock interviews are one way in which students can improve their job-seeking skills.','a face-to-face interview (= in which people meet in person ) I had to do a face-to-face interview followed by an entry test.','a telephone interview The first stage is a telephone interview.','interview technique The book gives some useful advice on interview technique.','an interview question Some of the interview questions were quite difficult to answer.','the interview panel (= the group of people interviewing someone ) The interview panel were very impressed with her enthusiasm.']::text[],'[{"sentence":"an interview for a job on the ‘Los Angeles Times’","translation":"مصاحبه برای کار در \"لس آنجلس تایمز\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000849.mp3"},{"sentence":"a portfolio of work presented at interview","translation":"نمونه کار ارائه شده در مصاحبه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001973341.mp3"}]'::jsonb,2),
('ccfe39f3-ffa8-55c0-80b7-b55198986359','6b28a5a7-c0ad-5925-a138-db221c77ef30',2,null,null,'spoken & written','an occasion when a famous person is asked questions about their life, experiences, or opinions for a newspaper , magazine , television programme etc','[ countable ]',null,'موقعیتی که برای یک روزنامه، مجله، برنامه تلویزیونی و غیره از یک فرد مشهور در مورد زندگی، تجربیات یا نظراتش سؤال می شود.','{}'::text[],'{}'::text[],array['have an interview She has an interview next week for a teaching job in Paris.','go for an interview ( also attend an interview formal ) I went for an interview at a software company yesterday.','get an interview He was one of only five people to get an interview out of more than 100 people who applied.','be called/invited for (an) interview Applicants who are called for interview may be asked to have a medical exam.','do an interview ( also conduct an interview formal ) The interview was conducted in French.','give somebody an interview (= interview someone ) We gave her an interview, but decided not to offer her the job.','a job interview Try to predict the questions you might get in your job interview.','an informal/formal interview Applicants will normally have an informal interview with the manager. One out of every six candidates reached the formal interview.','the first interview ( also the preliminary interview formal ) He felt the first interview had gone well.','a second/follow-up interview (= a more detailed interview after you have been successful in a previous interview ) She was asked back for a second interview.','a mock interview (= one that you do for practice, rather than a real interview ) Mock interviews are one way in which students can improve their job-seeking skills.','a face-to-face interview (= in which people meet in person ) I had to do a face-to-face interview followed by an entry test.','a telephone interview The first stage is a telephone interview.','interview technique The book gives some useful advice on interview technique.','an interview question Some of the interview questions were quite difficult to answer.','the interview panel (= the group of people interviewing someone ) The interview panel were very impressed with her enthusiasm.']::text[],'[{"sentence":"an interview with the president","translation":"مصاحبه با رئیس جمهور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001422317.mp3"},{"sentence":"Elton John gave an interview to Barbara Walters (= he answered her questions ) .","translation":"التون جان با باربارا والترز مصاحبه کرد (= او به سوالات او پاسخ داد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001723812.mp3"},{"sentence":"an exclusive interview (= one that is given to only one newspaper, programme etc )","translation":"یک مصاحبه اختصاصی (= مصاحبه ای که فقط به یک روزنامه، برنامه و غیره داده می شود)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001723818.mp3"}]'::jsonb,3),
